const $ = (s) => root.querySelector(s);
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
let onScreen = true;
const io = new IntersectionObserver((es) => {
  onScreen = es[es.length - 1].isIntersecting;
  root.classList.toggle('is-off', !onScreen);
});
io.observe(root);

root.addEventListener('click', (e) => { if (e.target.closest('a[href="#"]')) e.preventDefault(); });

/* ---- live latency window: the readouts are computed from the bars on screen ---- */
const bars = [...root.querySelectorAll('.bkf-bento-bars i')];
const chart = $('.bkf-bento-chart'), med = $('.bkf-bento-med');
const medOut = $('[data-k="med"]'), maxOut = $('[data-k="max"]');
const AXIS = 120;
let seed = 20261002;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
const sample = () => rnd() > 0.93 ? Math.round(74 + rnd() * 40) : Math.round(28 + rnd() * 12 + rnd() * 9);
const vals = bars.map(sample);
function draw() {
  bars.forEach((b, i) => {
    b.style.setProperty('--v', (vals[i] / AXIS).toFixed(3));
    b.classList.toggle('is-slow', vals[i] > 70);
  });
  const s = [...vals].sort((a, b) => a - b), h = s.length / 2;
  const m = Math.round((s[h - 1] + s[h]) / 2), mx = s[s.length - 1];
  medOut.textContent = m + ' ms';
  maxOut.textContent = mx + ' ms';
  med.style.setProperty('--v', (m / AXIS).toFixed(3));
  chart.setAttribute('aria-label', 'Last ' + s.length + ' writes: median ' + m + ' ms, slowest ' + mx + ' ms');
}
draw();
const tick = setInterval(() => {
  if (!root.isConnected) { clearInterval(tick); io.disconnect(); return; }
  if (document.hidden || !onScreen || reduce.matches) return;
  vals.shift(); vals.push(sample()); draw();
}, 1100);

/* ---- offline queue ---- */
const sw = $('.bkf-bento-switch'), list = $('.bkf-bento-tasks'), status = $('.bkf-bento-status');
const CHECK = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 12.5 9.5 17.5 19.5 6.5"/></svg>';
const CLOCK = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 7.5V12l3 2"/></svg>';
const pool = ['Book venue walkthrough', 'Send beta invites', 'Record the demo video', 'Update the status page', 'Brief the support team', 'Freeze API v4 schema'];
let next = 0, offline = false, queued = 0;
function syncItem(li) {
  if (!li.isConnected || !li.classList.contains('is-pending')) return;
  li.classList.remove('is-pending');
  li.classList.add('is-synced');
  li.querySelector('.bkf-bento-ti').innerHTML = CHECK;
}
$('.bkf-bento-add').addEventListener('click', () => {
  const li = document.createElement('li');
  li.className = 'bkf-bento-task is-pending';
  li.innerHTML = '<span class="bkf-bento-ti">' + CLOCK + '</span><span></span>';
  li.lastChild.textContent = pool[next++ % pool.length];
  list.append(li);
  while (list.children.length > 3) list.firstElementChild.remove();
  if (offline) {
    queued++;
    status.textContent = 'Offline · ' + queued + ' queued';
  } else {
    setTimeout(() => syncItem(li), 420);
  }
});
sw.addEventListener('click', () => {
  offline = !offline;
  sw.setAttribute('aria-checked', String(offline));
  if (offline) { status.textContent = 'Offline · ' + queued + ' queued'; return; }
  const n = queued, pending = [...list.querySelectorAll('.is-pending')];
  queued = 0;
  if (!n) { status.textContent = 'Online · in sync'; return; }
  status.textContent = 'Replaying ' + n + '…';
  pending.forEach((li, i) => setTimeout(() => syncItem(li), 160 + i * 150));
  setTimeout(() => {
    if (root.isConnected && !offline) status.textContent = 'Synced ' + n + (n > 1 ? ' ops' : ' op') + ' in ' + (29 + n * 6) + ' ms';
  }, 220 + pending.length * 150);
});

