@property --bkf-tabs-p { syntax: "<percentage>"; inherits: false; initial-value: 0%; }

.bkf-tabs {
  --bkf-tabs-bg: oklch(17.5% 0.014 165);
  --bkf-tabs-ink: oklch(95% 0.012 130);
  --bkf-tabs-accent: oklch(89% 0.19 128);
  --bkf-tabs-warn: oklch(73% 0.16 48);
  --bkf-tabs-surface: color-mix(in oklch, var(--bkf-tabs-ink) 5%, var(--bkf-tabs-bg));
