  --bkf-tabs-line: color-mix(in oklch, var(--bkf-tabs-ink) 11%, transparent);
  --bkf-tabs-line-2: color-mix(in oklch, var(--bkf-tabs-ink) 20%, transparent);
  --bkf-tabs-muted: color-mix(in oklch, var(--bkf-tabs-ink) 58%, var(--bkf-tabs-bg));
  --bkf-tabs-ease: cubic-bezier(.2, .9, .1, 1);
  --bkf-tabs-spring: linear(0, .009, .035 2.1%, .141, .281 6.7%, .723 12.9%, .938 16.7%, 1.017, 1.077, 1.121, 1.149 24.3%, 1.159, 1.163, 1.161, 1.154 29.9%, 1.129 32.8%, 1.051 39.6%, 1.017 43.1%, .991, .977 51%, .974 53.8%, .975 57.1%, .997 69.8%, 1.003 76.9%, 1);
  --bkf-tabs-dwell: 7s;
  container-name: bkf-tabs;
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  box-sizing: border-box;
  width: 100%;
