.bkf-tabs-list { grid-area: list; }
.bkf-tabs-stage { grid-area: stage; min-width: 0; }

@container bkf-tabs (min-width: 880px) {
  .bkf-tabs-in { column-gap: clamp(36px, 5cqi, 72px); row-gap: 32px; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); grid-template-rows: auto 1fr; grid-template-areas: "copy stage" "list stage"; }
