/* ---------- tab list ---------- */
.bkf-tabs-list {
  display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; margin-inline: -4px; padding: 4px 40px 4px 4px;
  scroll-snap-type: x proximity; scroll-padding-inline: 4px;
