  position: absolute; left: 14px; right: 14px; bottom: 5px; height: 2px; border-radius: 2px; overflow: hidden;
  opacity: 0; transition: opacity .3s;
  &::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, var(--bkf-tabs-accent) var(--bkf-tabs-p), var(--bkf-tabs-line) var(--bkf-tabs-p)); }
}
.bkf-tabs-tab[aria-selected="true"] .bkf-tabs-prog { opacity: 1; }
.bkf-tabs-tab[aria-selected="true"] .bkf-tabs-prog::after { animation: bkf-tabs-run var(--bkf-tabs-dwell) linear both; }
@keyframes bkf-tabs-run { from { --bkf-tabs-p: 0%; } to { --bkf-tabs-p: 100%; } }
.bkf-tabs:is(:hover, :focus-within, .is-off) .bkf-tabs-prog::after { animation-play-state: paused; }
.bkf-tabs[data-auto="off"] .bkf-tabs-prog { display: none; }

@container bkf-tabs (min-width: 880px) {
  .bkf-tabs-list { flex-direction: column; gap: 4px; overflow: visible; margin: 0 0 0 -14px; padding: 0; mask-image: none; }
