/* ---------- frame ---------- */
.bkf-tabs-frame {
  position: relative; overflow: hidden; display: grid; grid-template-rows: auto 1fr; border: 1px solid var(--bkf-tabs-line-2); border-radius: 18px;
  background: linear-gradient(180deg, var(--bkf-tabs-raised), var(--bkf-tabs-surface));
  box-shadow: 0 1px 0 color-mix(in oklch, var(--bkf-tabs-ink) 10%, transparent) inset, 0 40px 80px -40px oklch(0% 0 0 / .7);
}
.bkf-tabs-bar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 16px;
  border-bottom: 1px solid var(--bkf-tabs-line); font: 500 12px/1.2 ui-monospace, Menlo, monospace; color: var(--bkf-tabs-muted);
  & b { color: var(--bkf-tabs-ink); font-weight: 600; }
}
.bkf-tabs-crumb { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bkf-tabs-env { display: inline-flex; align-items: center; gap: 6px; flex: none; padding: 3px 8px; border: 1px solid var(--bkf-tabs-line-2); border-radius: 99px;
  & i { width: 6px; height: 6px; border-radius: 50%; background: var(--bkf-tabs-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkf-tabs-accent) 22%, transparent); }
}
.bkf-tabs-panel {
  display: grid; gap: 18px; align-content: start; min-height: 330px; padding: 20px;
  grid-template-columns: minmax(0, 1fr);
  grid-area: 2 / 1;
  &:focus-visible { outline: 2px solid var(--bkf-tabs-accent); outline-offset: -4px; border-radius: 0 0 16px 16px; }
  &[hidden] { display: grid; visibility: hidden; }
