}
@keyframes bkf-tabs-in { from { opacity: 0; transform: translateY(10px); filter: blur(6px); } }
@container bkf-tabs (min-width: 560px) {
  .bkf-tabs-panel[data-lay="side"] { grid-template-columns: minmax(0, 1fr) 150px; grid-template-areas: "body metric"; align-items: start; }
  .bkf-tabs-panel[data-lay="side"] > :not(.bkf-tabs-metric) { grid-area: body; }
  .bkf-tabs-panel[data-lay="side"] .bkf-tabs-metric { grid-area: metric; padding: 0 0 0 18px; border-left: 1px solid var(--bkf-tabs-line); text-align: right; }
