}
.bkf-tabs-metric {
  display: grid; gap: 4px; width: fit-content; max-width: 100%;
  & b { font: 650 clamp(34px, 5.2cqi, 48px)/1 system-ui, sans-serif; letter-spacing: -.04em; font-variant-numeric: tabular-nums; color: var(--bkf-tabs-accent); }
