@keyframes bkf-tabs-rise { from { opacity: 0; transform: translateY(8px); } }

/* previews */
.bkf-tabs-rows { display: grid; border: 1px solid var(--bkf-tabs-line); border-radius: 12px; overflow: hidden; }
.bkf-tabs-rows li { display: grid; grid-template-columns: minmax(0, 1fr) auto 64px; align-items: center; gap: 12px; padding: 11px 14px; font-size: 13.5px;
