.bkf-tabs-num { text-align: right; font: 500 12.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--bkf-tabs-muted); }
.bkf-tabs-mini { display: block; height: 4px; border-radius: 4px; background: var(--bkf-tabs-line); overflow: hidden;
  & i { display: block; height: 100%; background: var(--bkf-tabs-warn); transform-origin: 0 50%; animation: bkf-tabs-build 2.8s var(--bkf-tabs-ease) infinite; }
