.bkf-tabs-deploys { display: grid; gap: 14px; }
.bkf-tabs-dl { position: relative; display: grid; gap: 6px; }
.bkf-tabs-dl li {
  position: relative; display: grid; grid-template-columns: 46px minmax(0, 1fr) auto auto; align-items: center; gap: 10px;
  padding: 10px 12px; border: 1px solid var(--bkf-tabs-line); border-radius: 10px; font-size: 13px;
  transition: opacity .35s, border-color .35s, background-color .35s;
