.bkf-tabs-d318 .bkf-tabs-err { color: var(--bkf-tabs-warn); }
.bkf-tabs-live, .bkf-tabs-gone { padding: 2px 7px; border-radius: 99px; font-size: 11px; font-weight: 650; }
.bkf-tabs-live { background: var(--bkf-tabs-accent); color: var(--bkf-tabs-bg); transition: opacity .3s, transform .5s var(--bkf-tabs-spring); }
.bkf-tabs-gone { display: none; background: color-mix(in oklch, var(--bkf-tabs-warn) 18%, transparent); color: var(--bkf-tabs-warn); }
.bkf-tabs-d318 { border-color: color-mix(in oklch, var(--bkf-tabs-warn) 45%, transparent); background: color-mix(in oklch, var(--bkf-tabs-warn) 7%, transparent); }
.bkf-tabs-d317 .bkf-tabs-live { opacity: 0; transform: scale(.4); }
.bkf-tabs-deploys.is-rolled {
  & .bkf-tabs-d318 { opacity: .55; border-color: var(--bkf-tabs-line); background: none; }
  & .bkf-tabs-d318 .bkf-tabs-live { display: none; }
  & .bkf-tabs-d318 .bkf-tabs-gone { display: inline-block; }
  & .bkf-tabs-d318 .bkf-tabs-msg { text-decoration: line-through; text-decoration-color: var(--bkf-tabs-line-2); }
  & .bkf-tabs-d317 { border-color: color-mix(in oklch, var(--bkf-tabs-accent) 45%, transparent); background: color-mix(in oklch, var(--bkf-tabs-accent) 7%, transparent); }
  & .bkf-tabs-d317 .bkf-tabs-live { opacity: 1; transform: none; }
  & .bkf-tabs-rb-a { display: none; }
  & .bkf-tabs-rb-b { display: inline; }
}
.bkf-tabs-act { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; }
.bkf-tabs-rb {
  display: inline-flex; align-items: center; gap: 10px; height: 38px; padding: 0 8px 0 14px; border: 0; border-radius: 10px;
  background: var(--bkf-tabs-ink); color: var(--bkf-tabs-bg); font: 600 13.5px/1 system-ui, sans-serif; cursor: pointer;
  transition: transform .4s var(--bkf-tabs-spring), background-color .2s;
  &:hover { background: var(--bkf-tabs-accent); }
  &:active { transform: scale(.97); }
  &:focus-visible { outline: 2px solid var(--bkf-tabs-accent); outline-offset: 3px; }
  & kbd { padding: 3px 6px; border-radius: 6px; background: color-mix(in oklch, var(--bkf-tabs-bg) 14%, transparent); font: 600 11px/1 ui-monospace, Menlo, monospace; }
}
.bkf-tabs-rb-b { display: none; }
.bkf-tabs-rules { display: grid; gap: 8px; padding-top: 14px; border-top: 1px dashed var(--bkf-tabs-line-2);
  & > span { font-size: 12px; color: var(--bkf-tabs-muted); }
  & ul { display: flex; flex-wrap: wrap; gap: 6px; }
  & li { padding: 5px 9px; border: 1px solid var(--bkf-tabs-line); border-radius: 8px; font: 500 11.5px/1.2 ui-monospace, Menlo, monospace; color: var(--bkf-tabs-muted); }
  & b { font-weight: 600; color: var(--bkf-tabs-ink); }
}
.bkf-tabs-rbs { font: 500 12px/1.3 ui-monospace, Menlo, monospace; color: var(--bkf-tabs-muted); font-variant-numeric: tabular-nums; }

/* observe */
.bkf-tabs-chart { --bkf-tabs-ch: 150px; display: grid; gap: 6px;
  & svg { display: block; width: 100%; height: var(--bkf-tabs-ch); overflow: visible; }
  & figcaption { display: flex; justify-content: space-between; font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--bkf-tabs-muted); }
}
.bkf-tabs-grid { stroke: var(--bkf-tabs-line); stroke-width: 1; vector-effect: non-scaling-stroke; fill: none; }
.bkf-tabs-band { fill: color-mix(in oklch, var(--bkf-tabs-warn) 9%, transparent); }
.bkf-tabs-area { fill: color-mix(in oklch, var(--bkf-tabs-warn) 16%, transparent); }
.bkf-tabs-line { fill: none; stroke: var(--bkf-tabs-warn); stroke-width: 2; stroke-linejoin: round; vector-effect: non-scaling-stroke; stroke-dasharray: 1; }
.bkf-tabs-panel:not([hidden]) {
  & .bkf-tabs-area { animation: bkf-tabs-fade .9s .35s var(--bkf-tabs-ease) both; }
  & .bkf-tabs-line { animation: bkf-tabs-draw 1.2s .1s var(--bkf-tabs-ease) both; }
  & .bkf-tabs-mk { animation: bkf-tabs-fade .6s .5s var(--bkf-tabs-ease) both; }
}
@keyframes bkf-tabs-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes bkf-tabs-fade { from { opacity: 0; } }
.bkf-tabs-plot { position: relative; padding-top: 28px; }
.bkf-tabs-yl { position: absolute; right: 0; top: calc(28px + var(--y) * var(--bkf-tabs-ch) / 140); translate: 0 -120%; font: 500 10px/1 ui-monospace, Menlo, monospace; color: var(--bkf-tabs-muted); }
.bkf-tabs-mk {
  position: absolute; left: var(--x); top: 0; bottom: 0; translate: -100% 0; pointer-events: none;
  font: 600 11px/1 ui-monospace, Menlo, monospace; white-space: nowrap; color: var(--bkf-tabs-warn);
  padding: 4px 8px 0 0; border-right: 1px dashed currentColor;
  &.is-ok { translate: 0 0; padding: 4px 0 0 8px; border-right: 0; border-left: 1px dashed currentColor; color: var(--bkf-tabs-accent); }
}
.bkf-tabs-regions { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px;
  & li { display: flex; justify-content: space-between; align-items: baseline; padding: 9px 12px; border: 1px solid var(--bkf-tabs-line); border-radius: 10px; font: 500 12px/1 ui-monospace, Menlo, monospace; }
  & span { text-transform: uppercase; color: var(--bkf-tabs-muted); }
  & b { font-weight: 600; font-variant-numeric: tabular-nums; }
}

/* scale */
.bkf-tabs-scale { display: grid; gap: 8px; }
.bkf-tabs-hours { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 3px; align-items: end; height: 150px; padding-top: 10px; border-bottom: 1px solid var(--bkf-tabs-line-2);
  & i { display: block; height: 100%; border-radius: 3px 3px 0 0; background: linear-gradient(180deg, var(--bkf-tabs-accent), color-mix(in oklch, var(--bkf-tabs-accent) 35%, var(--bkf-tabs-bg)));
    transform-origin: 50% 100%; transform: scaleY(max(var(--v), .015)); }
  & i[data-zero] { background: var(--bkf-tabs-line-2); }
}
.bkf-tabs-panel:not([hidden]) .bkf-tabs-hours i { animation: bkf-tabs-grow .8s var(--bkf-tabs-spring) both; animation-delay: calc(100ms + var(--i) * 22ms); }
@keyframes bkf-tabs-grow { from { transform: scaleY(.015); } }
.bkf-tabs-axis { display: flex; justify-content: space-between; font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--bkf-tabs-muted); }
.bkf-tabs-kv { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 8px;
  & div { padding: 10px 12px; border: 1px solid var(--bkf-tabs-line); border-radius: 10px; }
  & dt { font-size: 11.5px; color: var(--bkf-tabs-muted); }
  & dd { margin-top: 2px; font: 600 15px/1.2 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
}

@container bkf-tabs (max-width: 459px) {
  .bkf-tabs-panel { padding: 16px; min-height: 0; }
  .bkf-tabs-rows li { grid-template-columns: minmax(0, 1fr) auto; }
  .bkf-tabs-rows .bkf-tabs-num { display: none; }
  .bkf-tabs-dl li { grid-template-columns: 42px minmax(0, 1fr) auto; }
  .bkf-tabs-dl .bkf-tabs-err { display: none; }
  .bkf-tabs-kv { grid-template-columns: 1fr 1fr; }
  .bkf-tabs-kv div:last-child { grid-column: 1 / -1; }
  .bkf-tabs-chart { --bkf-tabs-ch: 120px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkf-tabs .bkf-tabs-tab[aria-selected="true"] .bkf-tabs-prog::after { animation: none; --bkf-tabs-p: 0%; }
  .bkf-tabs .bkf-tabs-prog { display: none; }
  .bkf-tabs :is(.bkf-tabs-panel.is-in, .bkf-tabs-rows li, .bkf-tabs-dl li, .bkf-tabs-regions li, .bkf-tabs-hours i, .bkf-tabs-line, .bkf-tabs-area, .bkf-tabs-mini i, .bkf-tabs-mk) { animation: none !important; }
  .bkf-tabs .bkf-tabs-mini i { transform: scaleX(.62); }
  .bkf-tabs :is(.bkf-tabs-hl, .bkf-tabs-live, .bkf-tabs-rb) { transition-duration: .01s; }
}

