const tabs = [...root.querySelectorAll('.bkf-tabs-tab')];
const panels = [...root.querySelectorAll('.bkf-tabs-panel')];
const list = root.querySelector('.bkf-tabs-list');
const crumb = root.querySelector('.bkf-tabs-crumb b');
const frame = root.querySelector('.bkf-tabs-frame');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const uid = Math.random().toString(36).slice(2, 8);
const EASE = 'cubic-bezier(.2,.9,.1,1)';

/* unique ARIA ids so two copies of the section can share a page */
tabs.forEach((t, i) => {
  t.id = 'bkf-tabs-t' + i + '-' + uid;
  panels[i].id = 'bkf-tabs-p' + i + '-' + uid;
  t.setAttribute('aria-controls', panels[i].id);
  panels[i].setAttribute('aria-labelledby', t.id);
});
if (reduce.matches) root.dataset.auto = 'off';

let cur = 0;
/* view-transition names exist only for the length of a transition, and carry the
   instance id, so nothing else on the page can collide with them */
function name(i, on) {
  const set = (el, n) => { if (el) el.style.viewTransitionName = on ? 'bkf-tabs-' + n + '-' + uid : ''; };
  set(tabs[i].querySelector('.bkf-tabs-hl'), 'hl');
  set(panels[i].querySelector('.bkf-tabs-metric'), 'metric');
  set(panels[i], 'panel');
  set(frame, 'frame');
}
function apply(i) {
  tabs.forEach((t, k) => {
    const on = k === i;
    t.setAttribute('aria-selected', String(on));
    t.tabIndex = on ? 0 : -1;
    panels[k].hidden = !on;
  });
  crumb.textContent = panels[i].dataset.crumb;
  cur = i;
}
function tune() {
  for (const a of document.getAnimations()) {
    const pe = a.effect && a.effect.pseudoElement;
    if (pe && pe.indexOf(uid) > -1) a.effect.updateTiming({ duration: 520, easing: EASE });
  }
  const de = document.documentElement;
  de.animate([{ opacity: 0, transform: 'translateY(12px)', filter: 'blur(8px)' }, { opacity: 1, transform: 'none', filter: 'blur(0)' }],
    { duration: 520, easing: EASE, fill: 'both', pseudoElement: '::view-transition-new(bkf-tabs-panel-' + uid + ')' });
  de.animate([{ opacity: 1 }, { opacity: 0 }],
    { duration: 180, easing: 'cubic-bezier(.4,0,1,1)', fill: 'both', pseudoElement: '::view-transition-old(bkf-tabs-panel-' + uid + ')' });
}
function select(i, user) {
  if (user) root.dataset.auto = 'off';
  if (i === cur) return;
  const prev = cur;
  if (document.startViewTransition && !reduce.matches && root.isConnected && !document.hidden) {
    name(prev, true);
    const vt = document.startViewTransition(() => { name(prev, false); apply(i); name(i, true); });
    vt.ready.then(tune).catch(() => {});
    vt.finished.finally(() => name(cur, false));
  } else {
    apply(i);
    const p = panels[i];
    p.classList.remove('is-in');
    if (!reduce.matches) { void p.offsetWidth; p.classList.add('is-in'); }
  }
  const t = tabs[i];
  if (list.scrollWidth > list.clientWidth) list.scrollTo({ left: t.offsetLeft - 16, behavior: reduce.matches ? 'auto' : 'smooth' });
}

tabs.forEach((t, i) => t.addEventListener('click', () => select(i, true)));
list.addEventListener('keydown', (e) => {
  const n = tabs.length;
  const map = { ArrowRight: cur + 1, ArrowDown: cur + 1, ArrowLeft: cur - 1, ArrowUp: cur - 1, Home: 0, End: n - 1 };
  if (!(e.key in map)) return;
  e.preventDefault();
  const i = (map[e.key] + n) % n;
  select(i, true);
  tabs[i].focus();
});

/* autoplay: the active tab's progress bar is an @property animation; when it ends we advance */
root.addEventListener('animationend', (e) => {
  if (e.animationName !== 'bkf-tabs-run' || root.dataset.auto === 'off') return;
  select((cur + 1) % tabs.length, false);
});

/* rollback demo */
const dep = root.querySelector('.bkf-tabs-deploys');
const rbs = root.querySelector('.bkf-tabs-rbs');
const rb = root.querySelector('.bkf-tabs-rb');
rb.addEventListener('click', () => {
  root.dataset.auto = 'off';
  const on = dep.classList.toggle('is-rolled');
  rbs.textContent = on ? 'Rolled back to v317 in 3.9 s · errors 0.08%' : 'v318 is live · error rate 4.2%';
});
root.addEventListener('keydown', (e) => {
  if (cur === 1 && e.shiftKey && (e.key === 'R' || e.key === 'r') && !e.metaKey && !e.ctrlKey) { e.preventDefault(); rb.click(); }
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  root.classList.toggle('is-off', !es[es.length - 1].isIntersecting);
});
io.observe(root);

