.bkf-versus {
  --bkf-versus-paper: oklch(98.4% 0.004 100);
  --bkf-versus-ink: oklch(14% 0 0);
  --bkf-versus-hi: oklch(92.5% 0.19 106);
  --bkf-versus-gray: color-mix(in oklch, var(--bkf-versus-ink) 55%, var(--bkf-versus-paper));
  --bkf-versus-tint: color-mix(in oklch, var(--bkf-versus-ink) 6%, var(--bkf-versus-paper));
  --bkf-versus-b: 2px solid var(--bkf-versus-ink);
  --bkf-versus-snap: cubic-bezier(.75, 0, .15, 1);
  --bkf-versus-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  container-name: bkf-versus;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkf-versus-paper);
  color: var(--bkf-versus-ink);
  font: 400 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, figure, fieldset, legend) { margin: 0; padding: 0; }
  & :where(fieldset) { border: 0; min-width: 0; }
}
.bkf-versus-in { max-width: 1240px; margin-inline: auto; padding: clamp(28px, 6cqi, 76px) clamp(16px, 4.5cqi, 56px); }
.bkf-versus-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- top ---------- */
.bkf-versus-top { display: grid; gap: 28px; grid-template-columns: minmax(0, 1fr); grid-template-areas: "head" "bench"; }
.bkf-versus-head { grid-area: head; }
.bkf-versus-bench { grid-area: bench; }
@container bkf-versus (min-width: 900px) {
  .bkf-versus-top { grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); grid-template-areas: "head bench"; gap: 48px; align-items: end; }
}
.bkf-versus-kicker {
  display: flex; flex-wrap: wrap; gap: 0; width: fit-content; border: var(--bkf-versus-b);
  font: 700 11px/1 var(--bkf-versus-mono); text-transform: uppercase; letter-spacing: .1em;
  & span { padding: 7px 10px; }
  & span:first-child { background: var(--bkf-versus-ink); color: var(--bkf-versus-paper); }
}
.bkf-versus-title {
  margin-top: 20px; font-size: clamp(38px, 7cqi, 86px); line-height: .88; font-weight: 900;
  letter-spacing: -.05em; text-transform: uppercase; text-wrap: balance;
  & mark { padding: 0 .08em; margin-left: -.04em; background: var(--bkf-versus-hi); color: inherit; box-shadow: .06em .06em 0 var(--bkf-versus-ink); }
}
.bkf-versus-lede { margin-top: 20px; max-width: 52ch; font-size: clamp(15px, 1.5cqi, 17px); text-wrap: pretty; }

.bkf-versus-bench { border: 3px solid var(--bkf-versus-ink); background: var(--bkf-versus-paper); box-shadow: 8px 8px 0 var(--bkf-versus-ink);
  & figcaption { display: flex; justify-content: space-between; gap: 12px; padding: 9px 12px; background: var(--bkf-versus-ink); color: var(--bkf-versus-paper);
    font: 700 11px/1.2 var(--bkf-versus-mono); text-transform: uppercase; letter-spacing: .08em;
    & span:last-child { color: var(--bkf-versus-hi); } }
}
.bkf-versus-bars { display: grid; gap: 12px; padding: 18px 14px 14px; }
.bkf-versus-bar { display: grid; grid-template-columns: 104px minmax(0, 1fr) 68px; align-items: center; gap: 10px; }
.bkf-versus-who { font: 700 12px/1 var(--bkf-versus-mono); text-transform: uppercase; letter-spacing: .04em; }
.bkf-versus-track { height: 22px; border: var(--bkf-versus-b); }
.bkf-versus-fill {
  display: block; height: 100%; width: calc(var(--v) * 100%); background: var(--bkf-versus-ink); transform-origin: 0 50%;
  transform: scaleX(var(--p, 1));
}
.bkf-versus-bar.is-us .bkf-versus-fill { background: var(--bkf-versus-hi); box-shadow: inset -2px 0 0 var(--bkf-versus-ink); }
.bkf-versus-t { font: 700 13px/1 var(--bkf-versus-mono); font-variant-numeric: tabular-nums; text-align: right; }
.bkf-versus-delta {
  display: flex; align-items: center; gap: 14px; margin: 4px 14px 16px; padding-top: 14px; border-top: var(--bkf-versus-b);
  & b { padding: 4px 10px; background: var(--bkf-versus-hi); border: var(--bkf-versus-b); font: 900 clamp(26px, 3.4cqi, 36px)/1 system-ui, sans-serif; letter-spacing: -.04em; rotate: -3deg; box-shadow: 3px 3px 0 var(--bkf-versus-ink);
    transition: rotate .5s var(--bkf-versus-snap); }
  & span { font: 600 12.5px/1.35 var(--bkf-versus-mono); text-transform: uppercase; letter-spacing: .02em; }
}
.bkf-versus-bench:hover .bkf-versus-delta b { rotate: 2deg; }

/* ---------- controls ---------- */
.bkf-versus-controls { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 14px; margin-top: 44px; margin-bottom: 14px; }
.bkf-versus-pick { display: none; flex-wrap: wrap; align-items: center; gap: 0;
  & legend { float: left; width: 100%; margin-bottom: 8px; font: 700 11px/1 var(--bkf-versus-mono); text-transform: uppercase; letter-spacing: .08em; }
  & label { position: relative; flex: 1 1 0; cursor: pointer; }
  & label + label { margin-left: -2px; }
  & input { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; }
  & label span { display: block; padding: 10px 12px; border: var(--bkf-versus-b); text-align: center; font: 700 12px/1 var(--bkf-versus-mono); text-transform: uppercase; letter-spacing: .04em; transition: background-color .15s, color .15s; }
  & input:checked + span { background: var(--bkf-versus-ink); color: var(--bkf-versus-hi); }
  & input:focus-visible + span { outline: 3px solid var(--bkf-versus-hi); outline-offset: -6px; }
}
.bkf-versus-diff {
  position: relative; display: inline-flex; align-items: center; gap: 10px; padding: 9px 14px 9px 10px; border: var(--bkf-versus-b);
  background: var(--bkf-versus-paper); box-shadow: 4px 4px 0 var(--bkf-versus-ink); cursor: pointer; user-select: none;
  font: 700 12px/1 var(--bkf-versus-mono); text-transform: uppercase; letter-spacing: .05em;
  transition: transform .12s var(--bkf-versus-snap), box-shadow .12s var(--bkf-versus-snap);
  &:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 var(--bkf-versus-ink); }
  & input { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; }
  &:has(input:focus-visible) { outline: 3px solid var(--bkf-versus-ink); outline-offset: 3px; }
  &:has(input:checked) { background: var(--bkf-versus-hi); }
}
.bkf-versus-box { position: relative; width: 18px; height: 18px; border: var(--bkf-versus-b); background: var(--bkf-versus-paper);
  &::after { content: ""; position: absolute; inset: 3px; background: var(--bkf-versus-ink); transform: scale(0); transition: transform .18s var(--bkf-versus-snap); }
}
.bkf-versus-diff:has(input:checked) .bkf-versus-box::after { transform: none; }

/* ---------- table ---------- */
.bkf-versus-wrap { counter-reset: bkf-versus-rows; }
.bkf-versus-table {
  width: 100%; border-collapse: collapse; table-layout: fixed; border: 3px solid var(--bkf-versus-ink);
  background: var(--bkf-versus-paper);
  & th, & td { padding: 10px 14px; border: var(--bkf-versus-b); text-align: left; vertical-align: middle; transition: background-color .15s, color .15s; }
  & thead th { background: var(--bkf-versus-ink); color: var(--bkf-versus-paper); font: 700 12px/1.1 var(--bkf-versus-mono); text-transform: uppercase; letter-spacing: .06em; border-color: var(--bkf-versus-paper) var(--bkf-versus-ink); }
  & thead th:first-child { width: 40%; }
  & thead th[data-col="us"] { background: var(--bkf-versus-hi); color: var(--bkf-versus-ink); border-color: var(--bkf-versus-ink); font-size: 13px; }
  & tbody th { font-weight: 650; font-size: 14.5px; line-height: 1.3; text-wrap: balance; }
  & tbody tr { counter-increment: bkf-versus-rows; }
  & tbody tr:hover th { box-shadow: inset 6px 0 0 var(--bkf-versus-ink); }
  & td[data-col="us"] { background: color-mix(in oklch, var(--bkf-versus-hi) 55%, var(--bkf-versus-paper)); }
  & small { display: block; font: 600 11px/1.25 var(--bkf-versus-mono); color: var(--bkf-versus-gray); text-transform: uppercase; letter-spacing: .02em; }
}
.bkf-versus-c { display: flex; align-items: center; gap: 9px; min-width: 0; }
.bkf-versus-txt { font: 700 13.5px/1.25 var(--bkf-versus-mono); letter-spacing: -.01em; }
td[data-col="us"] .bkf-versus-txt { font-size: 14.5px; }
.bkf-versus-m { display: block; flex: none; width: 22px; height: 22px; fill: none; stroke: var(--bkf-versus-ink); stroke-width: 2.4; stroke-linecap: square;
  &.is-no { stroke: var(--bkf-versus-gray); }
}
.bkf-versus-half { fill: var(--bkf-versus-ink); stroke: none; }

/* column focus: hover any cell and its whole column inverts its header and tints the body */
.bkf-versus-table:has([data-col="ci"]:hover) td[data-col="ci"],
.bkf-versus-table:has([data-col="sh"]:hover) td[data-col="sh"] { background: var(--bkf-versus-tint); }
.bkf-versus-table:has([data-col="us"]:hover) td[data-col="us"] { background: var(--bkf-versus-hi); }
.bkf-versus-table:has([data-col="ci"]:hover) thead th[data-col="ci"],
.bkf-versus-table:has([data-col="sh"]:hover) thead th[data-col="sh"] { background: var(--bkf-versus-hi); color: var(--bkf-versus-ink); }

/* filter rows: rows where Shunt matches both competitors */
.bkf-versus:has(.bkf-versus-diff input:checked) tr[data-eq~="ci"][data-eq~="sh"] { display: none; }

.bkf-versus-count { display: flex; justify-content: flex-end; margin-top: 10px; font: 700 11px/1 var(--bkf-versus-mono); text-transform: uppercase; letter-spacing: .08em;
  &::after { content: "Showing " counter(bkf-versus-rows) " of 11 rows"; }
}
.bkf-versus-fine { margin-top: 22px; max-width: 80ch; font: 500 11.5px/1.5 var(--bkf-versus-mono); color: var(--bkf-versus-gray); text-wrap: pretty; }

.bkf-versus.is-in tbody tr { animation: bkf-versus-in .5s var(--bkf-versus-snap) both; animation-delay: calc(var(--i) * 35ms); }
@keyframes bkf-versus-in { from { opacity: 0; transform: translateX(-12px); } }

/* ---------- narrow: pick one competitor ---------- */
@container bkf-versus (max-width: 639px) {
  .bkf-versus-pick { display: flex; width: 100%; }
  .bkf-versus-diff { width: 100%; justify-content: center; }
  .bkf-versus:has(.bkf-versus-pick input[value="ci"]:checked) [data-col="sh"],
  .bkf-versus:has(.bkf-versus-pick input[value="sh"]:checked) [data-col="ci"] { display: none; }
  .bkf-versus:has(.bkf-versus-diff input:checked):has(.bkf-versus-pick input[value="ci"]:checked) tr[data-eq~="ci"],
  .bkf-versus:has(.bkf-versus-diff input:checked):has(.bkf-versus-pick input[value="sh"]:checked) tr[data-eq~="sh"] { display: none; }
  .bkf-versus-c { flex-direction: column; align-items: flex-start; gap: 4px; }
  .bkf-versus-table { & th, & td { padding: 10px; } & thead th:first-child { width: 46%; } & tbody th { font-size: 13.5px; } }
  .bkf-versus-txt { font-size: 12.5px; }
  .bkf-versus-bar { grid-template-columns: 88px minmax(0, 1fr) 62px; gap: 8px; }
  .bkf-versus-who { font-size: 11px; }
  .bkf-versus-bench { box-shadow: 5px 5px 0 var(--bkf-versus-ink); }
}

@media (prefers-reduced-motion: reduce) {
  .bkf-versus .bkf-versus-fill { transform: none; }
  .bkf-versus.is-in tbody tr { animation: none; }
  .bkf-versus .bkf-versus-delta b { transition: none; }
}

