const reduce = matchMedia('(prefers-reduced-motion: reduce)');
/* radio groups are global by name: give this instance its own */
const group = 'bkf-versus-col-' + Math.random().toString(36).slice(2, 8);
root.querySelectorAll('.bkf-versus-pick input').forEach((r) => { r.name = group; });

/* one clock drives both the bar and its number, so they agree on every frame */
const bars = [...root.querySelectorAll('.bkf-versus-bar')];
const fmt = (s) => Math.floor(s / 60) + 'm ' + String(Math.floor(s) % 60).padStart(2, '0') + 's';
const ease = (x) => (x >= 1 ? 1 : 1 - Math.pow(2, -10 * x));
function set(bar, k) {
  const t = bar.querySelector('.bkf-versus-t');
  bar.style.setProperty('--p', k.toFixed(4));
  t.textContent = fmt(Number(t.dataset.s) * k);
}
function countUp() {
  const t0 = performance.now(), D = 1300, STAG = 140;
  const frame = (now) => {
    if (!root.isConnected) return;
    let done = true;
    bars.forEach((b, i) => {
      const x = Math.max(0, Math.min(1, (now - t0 - i * STAG) / D));
      if (x < 1) done = false;
      set(b, ease(x));
    });
    if (!done) requestAnimationFrame(frame);
  };
  requestAnimationFrame(frame);
}
if (reduce.matches || !('IntersectionObserver' in window)) {
  root.classList.add('is-in');
} else {
  bars.forEach((b) => set(b, 0));
  const io = new IntersectionObserver((es) => {
    if (!root.isConnected) { io.disconnect(); return; }
    if (es.some((e) => e.isIntersecting)) {
      io.disconnect();
      root.classList.add('is-in');
      countUp();
    }
  }, { threshold: 0, rootMargin: '0px 0px -18% 0px' });
  io.observe(root);
}

