@property --bkf-steps-t { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --bkf-steps-orders { syntax: "<integer>"; inherits: false; initial-value: 64; }
@property --bkf-steps-picked { syntax: "<integer>"; inherits: false; initial-value: 61; }

.bkf-steps {
  --bkf-steps-bg: oklch(96.6% 0.028 86);
  --bkf-steps-ink: oklch(27% 0.045 45);
  --bkf-steps-card: oklch(99.2% 0.01 86);
  --bkf-steps-c0: oklch(72% 0.15 33);
  --bkf-steps-c1: oklch(85% 0.135 88);
  --bkf-steps-c2: oklch(77% 0.09 150);
  --bkf-steps-c3: oklch(76% 0.11 352);
  --bkf-steps-muted: color-mix(in oklch, var(--bkf-steps-ink) 62%, var(--bkf-steps-bg));
  --bkf-steps-line: color-mix(in oklch, var(--bkf-steps-ink) 14%, transparent);
  --bkf-steps-dwell: 5.6s;
  --bkf-steps-ease: cubic-bezier(.22, 1, .36, 1);
  --bkf-steps-spring: linear(0, .009, .035 2.1%, .141, .281 6.7%, .723 12.9%, .938 16.7%, 1.017, 1.077, 1.121, 1.149 24.3%, 1.159, 1.163, 1.161, 1.154 29.9%, 1.129 32.8%, 1.051 39.6%, 1.017 43.1%, .991, .977 51%, .974 53.8%, .975 57.1%, .997 69.8%, 1.003 76.9%, 1);
  --bkf-steps-round: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", sans-serif;
  container-name: bkf-steps;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(60% 50% at 100% 0%, color-mix(in oklch, var(--bkf-steps-c1) 30%, transparent), transparent 70%),
    radial-gradient(50% 45% at 0% 100%, color-mix(in oklch, var(--bkf-steps-c3) 22%, transparent), transparent 70%),
    var(--bkf-steps-bg);
  color: var(--bkf-steps-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul, ol, figure) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
}
.bkf-steps-in { max-width: 1240px; margin-inline: auto; padding: clamp(32px, 6cqi, 76px) clamp(16px, 4.5cqi, 56px); }

.bkf-steps-head { max-width: 760px; }
.bkf-steps-eyebrow { display: flex; align-items: center; gap: 8px; font: 700 14px/1 var(--bkf-steps-round);
  & svg { width: 24px; height: 24px; fill: var(--bkf-steps-c1); stroke: var(--bkf-steps-ink); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & span { font-weight: 500; color: var(--bkf-steps-muted); }
}
.bkf-steps-title { margin-top: 16px; font: 800 clamp(30px, 5cqi, 56px)/1.02 var(--bkf-steps-round); letter-spacing: -.03em; text-wrap: balance; }
.bkf-steps-lede { margin-top: 14px; max-width: 50ch; font-size: clamp(15px, 1.5cqi, 17px); color: var(--bkf-steps-muted); text-wrap: pretty; }

/* ---------- rail ---------- */
.bkf-steps-rail { position: relative; display: grid; margin-top: clamp(28px, 4cqi, 44px); grid-template-columns: minmax(0, 1fr); }
.bkf-steps-item { position: relative; --dot: 46px; }
.bkf-steps-btn {
  position: relative; z-index: 1; display: grid; grid-template-columns: var(--dot) minmax(0, 1fr); grid-template-areas: "dot name" "dot desc";
  column-gap: 14px; align-items: start; width: 100%; padding: 0 0 22px; border: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer;
  border-radius: 16px;
  &:focus-visible { outline: 3px solid var(--bkf-steps-ink); outline-offset: 4px; }
}
.bkf-steps-dot {
  grid-area: dot; position: relative; display: grid; place-items: center; width: var(--dot); height: var(--dot); border-radius: 50%;
  border: 2.5px solid var(--bkf-steps-ink); background: var(--bkf-steps-card);
  font: 800 17px/1 var(--bkf-steps-round); font-variant-numeric: tabular-nums;
  transition: background-color .35s, transform .6s var(--bkf-steps-spring), box-shadow .35s;
  & svg { position: absolute; width: 22px; height: 22px; fill: none; stroke: var(--bkf-steps-ink); stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 24; stroke-dashoffset: 24; transition: stroke-dashoffset .5s .1s var(--bkf-steps-ease); }
}
.bkf-steps-n { transition: opacity .2s, transform .4s var(--bkf-steps-spring); }
.bkf-steps-name { grid-area: name; padding-top: 4px; font: 750 17px/1.25 var(--bkf-steps-round); letter-spacing: -.01em; text-wrap: balance; }
.bkf-steps-desc { grid-area: desc; margin-top: 4px; font-size: 14px; line-height: 1.45; color: var(--bkf-steps-muted); text-wrap: pretty; }
.bkf-steps-item[data-state="todo"] .bkf-steps-name { color: var(--bkf-steps-muted); }
.bkf-steps-item[data-state="current"] .bkf-steps-dot { background: var(--c); transform: scale(1.12); box-shadow: 0 0 0 6px color-mix(in oklch, var(--c) 30%, transparent); }
.bkf-steps-item[data-state="done"] .bkf-steps-dot { background: var(--c); }
.bkf-steps-item[data-state="done"] .bkf-steps-n { opacity: 0; transform: scale(.4); }
.bkf-steps-item[data-state="done"] .bkf-steps-dot svg { stroke-dashoffset: 0; }
.bkf-steps-btn:hover .bkf-steps-dot { transform: scale(1.08) rotate(-6deg); }
.bkf-steps-item[data-state="current"] .bkf-steps-btn:hover .bkf-steps-dot { transform: scale(1.14) rotate(-6deg); }

/* progress line, one segment per gap; fill = clamp(0, k + t - j, 1) where t is the dwell timer */
.bkf-steps-seg {
  position: absolute; z-index: 0; left: calc(var(--dot) / 2 - 3px); top: calc(var(--dot) / 2); width: 6px; height: 100%;
  border-radius: 6px; background: var(--bkf-steps-line); overflow: hidden;
  & i { position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(180deg, var(--c), var(--cn));
    transform-origin: 50% 0; transform: scaleY(clamp(0, calc(var(--bkf-steps-k, 0) + var(--bkf-steps-t) - var(--j)), 1)); }
}
.bkf-steps-rail[data-jump] .bkf-steps-seg i { transition: transform .9s var(--bkf-steps-spring); }
.bkf-steps-rail[data-run] { animation: bkf-steps-dwell var(--bkf-steps-dwell) linear forwards; }
@keyframes bkf-steps-dwell { from { --bkf-steps-t: 0; } to { --bkf-steps-t: 1; } }
.bkf-steps:is(:hover, .is-off) .bkf-steps-rail[data-run] { animation-play-state: paused; }

@container bkf-steps (min-width: 760px) {
  .bkf-steps-rail { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .bkf-steps-btn { grid-template-columns: minmax(0, 1fr); grid-template-areas: "dot" "name" "desc"; justify-items: center; text-align: center; padding: 0 12px 6px; }
  .bkf-steps-name { padding-top: 14px; }
  .bkf-steps-desc { max-width: 28ch; }
  .bkf-steps-seg { left: 50%; top: calc(var(--dot) / 2 - 3px); width: 100%; height: 6px;
    & i { background: linear-gradient(90deg, var(--c), var(--cn)); transform-origin: 0 50%; transform: scaleX(clamp(0, calc(var(--bkf-steps-k, 0) + var(--bkf-steps-t) - var(--j)), 1)); }
  }
}

/* ---------- stage ---------- */
/* every scene shares one grid cell, so the stage is always as tall as the tallest scene and nothing below it jumps */
.bkf-steps-stage { display: grid; margin-top: clamp(24px, 3.4cqi, 40px); }
.bkf-steps-scene {
  display: grid; gap: 18px; grid-template-columns: minmax(0, 1fr); grid-template-areas: "art" "note";
  padding: clamp(16px, 2.6cqi, 28px); border: 2.5px solid var(--bkf-steps-ink); border-radius: 28px; background: var(--bkf-steps-card);
  box-shadow: 0 6px 0 var(--bkf-steps-ink);
  grid-area: 1 / 1;
  &[hidden] { display: grid; visibility: hidden; }
}
@container bkf-steps (min-width: 760px) {
  .bkf-steps-scene { grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr); grid-template-areas: "art note"; gap: clamp(20px, 3.6cqi, 48px); align-items: center; min-height: 320px; }
}
.bkf-steps-art { grid-area: art; min-width: 0; }
.bkf-steps-two { display: grid; gap: 14px; grid-template-columns: minmax(0, 1fr); align-items: center; }
@container bkf-steps (min-width: 560px) { .bkf-steps-two { grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); } }
.bkf-steps-note { grid-area: note; display: grid; gap: 10px; justify-items: start;
  & p { font-size: 15.5px; line-height: 1.5; text-wrap: pretty; }
}
.bkf-steps-big { font: 900 clamp(56px, 8cqi, 96px)/.85 var(--bkf-steps-round); letter-spacing: -.05em; color: transparent; -webkit-text-stroke: 2.5px var(--bkf-steps-ink);
  background: linear-gradient(var(--bkf-steps-scene-c, var(--bkf-steps-c0)) 0 0) 0 58% / 100% 42% no-repeat; -webkit-background-clip: text; background-clip: text; }
.bkf-steps-scene[data-s="1"] { --bkf-steps-scene-c: var(--bkf-steps-c1); }
.bkf-steps-scene[data-s="2"] { --bkf-steps-scene-c: var(--bkf-steps-c2); }
.bkf-steps-scene[data-s="3"] { --bkf-steps-scene-c: var(--bkf-steps-c3); }
.bkf-steps-chip { padding: 6px 12px; border: 2px solid var(--bkf-steps-ink); border-radius: 99px; background: var(--bkf-steps-scene-c, var(--bkf-steps-c0)); font: 700 13px/1 var(--bkf-steps-round); }

.bkf-steps-scene:not([hidden]) .bkf-steps-pop { animation: bkf-steps-pop .7s var(--bkf-steps-spring) both; animation-delay: calc(80ms + var(--i, 0) * 70ms); }
.bkf-steps-scene:not([hidden]) .bkf-steps-note { animation: bkf-steps-slide .6s var(--bkf-steps-ease) both; animation-delay: 120ms; }
@keyframes bkf-steps-pop { from { opacity: 0; transform: translateY(14px) scale(.96); } }
@keyframes bkf-steps-slide { from { opacity: 0; transform: translateX(16px); } }
.bkf-steps-sw { width: 12px; height: 12px; flex: none; border-radius: 4px; border: 1.5px solid var(--bkf-steps-ink); background: var(--c); }

/* scene 0: menu */
.bkf-steps-menu { position: relative; max-width: 500px; margin-inline: auto; padding: 16px 18px 18px; border: 2px solid var(--bkf-steps-ink); border-radius: 20px; background: var(--bkf-steps-bg); }
.bkf-steps-mh { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 4px 12px;
  & b { font: 800 18px/1.2 var(--bkf-steps-round); }
  & span { font-size: 12.5px; color: var(--bkf-steps-muted); }
}
.bkf-steps-cols, .bkf-steps-ml li { display: grid; grid-template-columns: 12px minmax(0, 1fr) 58px 34px; gap: 10px; align-items: center; }
.bkf-steps-cols { margin-top: 12px; padding-bottom: 6px; border-bottom: 1.5px dashed var(--bkf-steps-line); font: 600 10.5px/1 ui-monospace, Menlo, monospace; text-transform: uppercase; letter-spacing: .08em; color: var(--bkf-steps-muted);
  & span:first-child { grid-column: 2; } & span { text-align: right; } & span:first-child { text-align: left; } }
.bkf-steps-ml li { padding: 8px 0; border-bottom: 1.5px dashed var(--bkf-steps-line); font-size: 14px;
  & em, & small { font: 600 13px/1 ui-monospace, Menlo, monospace; font-style: normal; text-align: right; font-variant-numeric: tabular-nums; }
}
.bkf-steps-mn { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }
.bkf-steps-pub { position: relative; display: grid; margin-top: 14px; height: 40px; border: 2px solid var(--bkf-steps-ink); border-radius: 12px; overflow: visible; font: 750 14px/1 var(--bkf-steps-round);
  & > span { grid-area: 1 / 1; display: flex; align-items: center; justify-content: center; gap: 6px; border-radius: 10px; }
  & svg:not(.bkf-steps-hand) { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
}
.bkf-steps-pa { background: var(--bkf-steps-ink); color: var(--bkf-steps-card); }
.bkf-steps-pb { background: var(--bkf-steps-c2); color: var(--bkf-steps-ink); }
.bkf-steps-hand { position: absolute; right: 22%; top: 60%; width: 26px; height: 26px; fill: var(--bkf-steps-card); stroke: var(--bkf-steps-ink); stroke-width: 1.6; stroke-linejoin: round; opacity: 0; }
.bkf-steps-scene:not([hidden]) {
  & .bkf-steps-pa { animation: bkf-steps-out 3s linear both; }
  & .bkf-steps-pb { animation: bkf-steps-in 3s linear both; }
  & .bkf-steps-hand { animation: bkf-steps-hand 3s var(--bkf-steps-ease) both; }
  & .bkf-steps-pub { animation: bkf-steps-press 3s linear both; }
}
@keyframes bkf-steps-out { 0%, 58% { opacity: 1; } 62%, 100% { opacity: 0; } }
@keyframes bkf-steps-in { 0%, 58% { opacity: 0; transform: scale(.9); } 66%, 100% { opacity: 1; transform: none; } }
@keyframes bkf-steps-hand { 0%, 25% { opacity: 0; transform: translate(60px, 50px); } 35% { opacity: 1; } 52% { opacity: 1; transform: translate(0, 0); } 56% { transform: translate(0, 0) scale(.85); } 62% { transform: translate(0, 0); } 80% { opacity: 1; transform: translate(8px, 10px); } 100% { opacity: 0; transform: translate(30px, 40px); } }
@keyframes bkf-steps-press { 0%, 54% { transform: none; } 57% { transform: scale(.96); } 62%, 100% { transform: none; } }

/* scene 1: preorders */
.bkf-steps-caps { display: grid; gap: 10px; padding: 16px; border: 2px solid var(--bkf-steps-ink); border-radius: 20px; background: var(--bkf-steps-bg); }
.bkf-steps-ch { display: flex; justify-content: space-between; align-items: baseline;
  & b { font: 800 18px/1.2 var(--bkf-steps-round); }
}
.bkf-steps-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkf-steps-cnt { font: 800 15px/1 var(--bkf-steps-round); font-variant-numeric: tabular-nums; counter-reset: bkf-steps-o var(--bkf-steps-orders);
  &::before { content: counter(bkf-steps-o) " orders"; }
}
.bkf-steps-scene:not([hidden]) .bkf-steps-cnt { animation: bkf-steps-count 1.6s .3s cubic-bezier(.2, .7, .2, 1) both; }
@keyframes bkf-steps-count { from { --bkf-steps-orders: 0; } }
.bkf-steps-cap { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "n v" "bar bar"; gap: 5px 10px; align-items: baseline; font-size: 13.5px;
  & > span { grid-area: n; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & b { grid-area: v; font: 700 13px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; & span { color: var(--bkf-steps-muted); font-weight: 500; } }
  & i { grid-area: bar; display: block; height: 12px; border: 1.5px solid var(--bkf-steps-ink); border-radius: 99px; overflow: hidden; background: var(--bkf-steps-card); }
  & s { display: block; height: 100%; width: calc(var(--v) * 100%); border-radius: inherit; background: var(--c); transform-origin: 0 50%; }
}
.bkf-steps-scene:not([hidden]) .bkf-steps-cap s { animation: bkf-steps-bar 1.1s var(--bkf-steps-spring) both; animation-delay: calc(250ms + var(--i) * 110ms); }
@keyframes bkf-steps-bar { from { transform: scaleX(0); } }
.bkf-steps-cap[data-sold] b::after { content: "sold out"; margin-left: 8px; padding: 2px 7px; border-radius: 99px; background: var(--bkf-steps-ink); color: var(--bkf-steps-card); font: 700 10px/1 var(--bkf-steps-round); text-transform: uppercase; letter-spacing: .04em; vertical-align: 1px; }
.bkf-steps-feed { display: grid; gap: 8px;
  & li { display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 10px 12px; border: 2px solid var(--bkf-steps-ink); border-radius: 16px; background: var(--bkf-steps-card); box-shadow: 0 3px 0 var(--bkf-steps-ink); font-size: 13px; line-height: 1.35; }
  & li:nth-child(2) { rotate: 1.2deg; margin-left: 10px; }
  & li:nth-child(3) { rotate: -.8deg; }
  & i { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; border: 1.5px solid var(--bkf-steps-ink); background: var(--c); font: 800 10.5px/1 var(--bkf-steps-round); font-style: normal; }
  & b { display: block; font-weight: 700; }
  & time { font: 600 11.5px/1 ui-monospace, Menlo, monospace; color: var(--bkf-steps-muted); }
}

/* scene 2: oven */
.bkf-steps-oven { padding: 12px; border: 2.5px solid var(--bkf-steps-ink); border-radius: 22px; background: var(--bkf-steps-c0); box-shadow: inset 0 -6px 0 color-mix(in oklch, var(--bkf-steps-ink) 18%, transparent); }
.bkf-steps-ovtop { display: flex; justify-content: space-between; align-items: center; padding: 0 4px 10px; }
.bkf-steps-temp { padding: 4px 9px; border: 2px solid var(--bkf-steps-ink); border-radius: 8px; background: var(--bkf-steps-ink); color: var(--bkf-steps-c1); font: 700 12px/1 ui-monospace, Menlo, monospace; }
.bkf-steps-knobs { display: flex; gap: 8px;
  & i { width: 20px; height: 20px; border: 2px solid var(--bkf-steps-ink); border-radius: 50%; background: var(--bkf-steps-card); background-image: linear-gradient(var(--bkf-steps-ink), var(--bkf-steps-ink)); background-size: 2px 8px; background-position: 50% 2px; background-repeat: no-repeat; }
  & i:last-child { rotate: 120deg; }
}
.bkf-steps-window { position: relative; display: grid; align-items: end; height: 150px; padding: 0 14px 12px; border: 2.5px solid var(--bkf-steps-ink); border-radius: 14px; overflow: hidden;
