const items = [...root.querySelectorAll('.bkf-steps-item')];
const btns = items.map((li) => li.querySelector('.bkf-steps-btn'));
const scenes = [...root.querySelectorAll('.bkf-steps-scene')];
const rail = root.querySelector('.bkf-steps-rail');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
let k = 0, auto = !reduce.matches, jumpT = 0;

function restart() {
  rail.removeAttribute('data-run');
  if (!auto) return;
  void rail.offsetWidth;              /* restart the dwell animation from t = 0 */
  rail.setAttribute('data-run', '');
}
function go(i, smooth) {
  k = i;
  rail.style.setProperty('--bkf-steps-k', i);
  items.forEach((li, j) => { li.dataset.state = j < i ? 'done' : j === i ? 'current' : 'todo'; });
  btns.forEach((b, j) => { if (j === i) b.setAttribute('aria-current', 'step'); else b.removeAttribute('aria-current'); });
  scenes.forEach((s, j) => { s.hidden = j !== i; });
  if (smooth) {
    rail.setAttribute('data-jump', '');
    clearTimeout(jumpT);
    jumpT = setTimeout(() => rail.removeAttribute('data-jump'), 950);
  }
  restart();
}

rail.addEventListener('animationend', (e) => {
  if (e.target !== rail || e.animationName !== 'bkf-steps-dwell' || !auto || !root.isConnected) return;
  const n = (k + 1) % items.length;
  go(n, n === 0);
});
btns.forEach((b, j) => b.addEventListener('click', () => {
  auto = false;
  go(j, true);
}));
rail.addEventListener('keydown', (e) => {
  const map = { ArrowRight: k + 1, ArrowDown: k + 1, ArrowLeft: k - 1, ArrowUp: k - 1, Home: 0, End: items.length - 1 };
  if (!(e.key in map)) return;
  e.preventDefault();
  const i = Math.max(0, Math.min(items.length - 1, map[e.key]));
  auto = false;
  go(i, true);
  btns[i].focus();
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  root.classList.toggle('is-off', !es[es.length - 1].isIntersecting);
});
io.observe(root);
go(0, false);

