@property --bkf-orbit-a { syntax: "<angle>"; inherits: false; initial-value: 0deg; }

.bkf-orbit {
  --bkf-orbit-bg: oklch(17% 0.018 55);
  --bkf-orbit-ink: oklch(94% 0.02 85);
  --bkf-orbit-gold: oklch(82% 0.085 82);
  --bkf-orbit-out: oklch(78% 0.06 25);
  --bkf-orbit-muted: color-mix(in oklch, var(--bkf-orbit-ink) 56%, var(--bkf-orbit-bg));
  --bkf-orbit-line: color-mix(in oklch, var(--bkf-orbit-gold) 18%, transparent);
  --bkf-orbit-surface: color-mix(in oklch, var(--bkf-orbit-ink) 5%, var(--bkf-orbit-bg));
  --bkf-orbit-ease: cubic-bezier(.16, 1, .3, 1);
  --bkf-orbit-node: 48px;
  container-name: bkf-orbit;
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(55% 60% at 72% 50%, color-mix(in oklch, var(--bkf-orbit-gold) 9%, transparent), transparent 70%),
    var(--bkf-orbit-bg);
  color: var(--bkf-orbit-ink);
  font: 400 15px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul, dl, dd) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
}
.bkf-orbit-in {
  display: grid; gap: 28px; max-width: 1240px; margin-inline: auto; padding: clamp(32px, 6cqi, 80px) clamp(16px, 4.5cqi, 56px);
  grid-template-columns: minmax(0, 1fr); grid-template-areas: "copy" "stage" "card";
}
.bkf-orbit-copy { grid-area: copy; }
.bkf-orbit-stage { grid-area: stage; }
.bkf-orbit-card { grid-area: card; }
@container bkf-orbit (min-width: 900px) {
  .bkf-orbit-in { grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); grid-template-rows: auto 1fr; grid-template-areas: "copy stage" "card stage"; column-gap: clamp(32px, 5cqi, 72px); row-gap: 28px; align-items: start; }
  .bkf-orbit-stage { align-self: center; }
}

.bkf-orbit-eyebrow { font: 600 11.5px/1 system-ui, sans-serif; text-transform: uppercase; letter-spacing: .22em; color: var(--bkf-orbit-gold); }
.bkf-orbit-title { margin-top: 18px; font-size: clamp(32px, 4.8cqi, 54px); line-height: 1.04; font-weight: 300; letter-spacing: -.035em; text-wrap: balance; }
.bkf-orbit-lede { margin-top: 18px; max-width: 46ch; color: var(--bkf-orbit-muted); font-size: clamp(15px, 1.45cqi, 16.5px); text-wrap: pretty; }

/* ---------- stage ---------- */
.bkf-orbit-stage {
  position: relative; width: 100%; max-width: 600px; aspect-ratio: 1; margin-inline: auto;
  container-name: bkf-orbit-stage; container-type: inline-size;
  --r1: calc(50cqi - var(--bkf-orbit-node) / 2 - 8px);
  --r0: calc(var(--r1) * .56);
}
.bkf-orbit-cv { position: absolute; inset: 0; width: 100%; height: 100%; }
.bkf-orbit-hub {
  position: absolute; left: 50%; top: 50%; width: 96px; height: 96px; margin: -48px 0 0 -48px; border-radius: 50%;
  display: grid; place-content: center; justify-items: center; gap: 2px;
  background: radial-gradient(circle at 50% 35%, color-mix(in oklch, var(--bkf-orbit-gold) 22%, var(--bkf-orbit-bg)), var(--bkf-orbit-bg) 75%);
  border: 1px solid color-mix(in oklch, var(--bkf-orbit-gold) 45%, transparent);
  box-shadow: 0 0 0 10px color-mix(in oklch, var(--bkf-orbit-gold) 5%, transparent), 0 20px 60px -10px oklch(0% 0 0 / .6);
  & svg { width: 34px; height: 34px; fill: none; stroke: var(--bkf-orbit-gold); stroke-width: 1.4; }
  & span { font: 600 9.5px/1 system-ui, sans-serif; text-transform: uppercase; letter-spacing: .2em; color: var(--bkf-orbit-gold); }
  &::before { content: ""; position: absolute; inset: -7px; border-radius: 50%; padding: 1.5px;
    background: conic-gradient(from var(--bkf-orbit-a), transparent 0 55%, var(--bkf-orbit-gold) 80%, transparent 100%);
    mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
    animation: bkf-orbit-spin 6s linear infinite; }
}
@keyframes bkf-orbit-spin { to { --bkf-orbit-a: 360deg; } }

.bkf-orbit-nodes { position: absolute; inset: 0; }
.bkf-orbit-node {
  --a: calc(var(--k) / var(--of) * 1turn + var(--off, 0deg));
  position: absolute; left: 50%; top: 50%; width: var(--bkf-orbit-node); height: var(--bkf-orbit-node);
  margin: calc(var(--bkf-orbit-node) / -2) 0 0 calc(var(--bkf-orbit-node) / -2);
  display: grid; place-items: center; padding: 0; border-radius: 50%; cursor: pointer;
  border: 1px solid color-mix(in oklch, var(--bkf-orbit-gold) 30%, transparent);
  background: color-mix(in oklch, var(--bkf-orbit-ink) 7%, var(--bkf-orbit-bg));
  color: var(--bkf-orbit-ink);
  transform: rotate(var(--a)) translateX(var(--r0)) rotate(calc(-1 * var(--a)));
  transition: border-color .3s, background-color .3s, color .3s, opacity .3s, box-shadow .4s var(--bkf-orbit-ease), scale .5s var(--bkf-orbit-ease);
  & svg { width: 46%; height: 46%; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  &[data-ring="1"] { --off: -14deg; transform: rotate(var(--a)) translateX(var(--r1)) rotate(calc(-1 * var(--a))); }
  &:hover, &:focus-visible, &.is-on { border-color: var(--bkf-orbit-gold); color: var(--bkf-orbit-gold); scale: 1.12; box-shadow: 0 0 0 6px color-mix(in oklch, var(--bkf-orbit-gold) 12%, transparent), 0 12px 30px -8px oklch(0% 0 0 / .7); }
  &:focus-visible { outline: 2px solid var(--bkf-orbit-gold); outline-offset: 4px; }
  &[aria-pressed="true"] { background: var(--bkf-orbit-gold); color: var(--bkf-orbit-bg); }
}
.bkf-orbit-stage:has(.bkf-orbit-node.is-on) .bkf-orbit-node:not(.is-on) { opacity: .5; }

/* ---------- card ---------- */
.bkf-orbit-card { display: grid; gap: 14px; max-width: 520px; }
.bkf-orbit-cbody { padding: 18px 20px 20px; border: 1px solid var(--bkf-orbit-line); border-radius: 16px;
  background: linear-gradient(180deg, color-mix(in oklch, var(--bkf-orbit-gold) 6%, var(--bkf-orbit-surface)), var(--bkf-orbit-surface)); }
.bkf-orbit-cbody.is-swap > * { animation: bkf-orbit-swap .45s var(--bkf-orbit-ease) both; }
.bkf-orbit-cbody.is-swap > :nth-child(2) { animation-delay: 40ms; }
.bkf-orbit-cbody.is-swap > :nth-child(3) { animation-delay: 80ms; }
@keyframes bkf-orbit-swap { from { opacity: 0; transform: translateY(6px); filter: blur(3px); } }
.bkf-orbit-ch { display: flex; align-items: center; gap: 12px;
  & b { display: block; font-size: 17px; font-weight: 600; letter-spacing: -.01em; }
  & div > span { font-size: 13px; color: var(--bkf-orbit-muted); }
}
.bkf-orbit-cl { display: grid; place-items: center; flex: none; width: 42px; height: 42px; border-radius: 50%; border: 1px solid color-mix(in oklch, var(--bkf-orbit-gold) 45%, transparent); color: var(--bkf-orbit-gold);
  & svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
}
.bkf-orbit-cs { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--bkf-orbit-line);
  & dt { font-size: 11px; text-transform: uppercase; letter-spacing: .12em; color: var(--bkf-orbit-muted); }
  & dd { margin-top: 4px; font: 500 18px/1.2 system-ui, sans-serif; letter-spacing: -.01em; font-variant-numeric: tabular-nums; }
}
.bkf-orbit-bar { height: 3px; margin-top: 14px; border-radius: 3px; background: var(--bkf-orbit-line); overflow: hidden;
  & i { display: block; height: 100%; background: var(--bkf-orbit-gold); transform-origin: 0 50%; transform: scaleX(var(--s, 1)); transition: transform .7s var(--bkf-orbit-ease); }
}
.bkf-orbit-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 16px; font-size: 12.5px; color: var(--bkf-orbit-muted);
  & .is-in, & .is-out { display: inline-flex; align-items: center; gap: 7px; }
  & .is-in::before, & .is-out::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--bkf-orbit-gold); box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkf-orbit-gold) 18%, transparent); }
  & .is-out::before { background: var(--bkf-orbit-out); box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkf-orbit-out) 18%, transparent); }
}
.bkf-orbit-hint { flex-basis: 100%; }

@container bkf-orbit (max-width: 520px) {
  .bkf-orbit-stage { --bkf-orbit-node: 38px; }
  .bkf-orbit-hub { width: 74px; height: 74px; margin: -37px 0 0 -37px; & svg { width: 26px; height: 26px; } }
  .bkf-orbit-cs { grid-template-columns: 1fr 1fr; & div:last-child { grid-column: 1 / -1; } }
}

.bkf-orbit.is-off .bkf-orbit-hub::before { animation-play-state: paused; }

@media (prefers-reduced-motion: reduce) {
  .bkf-orbit .bkf-orbit-hub::before { animation: none; --bkf-orbit-a: 200deg; }
  .bkf-orbit .bkf-orbit-cbody.is-swap > * { animation: none; }
  .bkf-orbit :is(.bkf-orbit-node, .bkf-orbit-bar i) { transition-duration: .01s; }
}

