const stage = root.querySelector('.bkf-orbit-stage');
const cv = root.querySelector('.bkf-orbit-cv');
const ctx = cv.getContext('2d');
const btns = [...root.querySelectorAll('.bkf-orbit-node')];
const card = root.querySelector('.bkf-orbit-cbody');
const out = {
  logo: root.querySelector('.bkf-orbit-cl'), name: root.querySelector('.bkf-orbit-cn'), cat: root.querySelector('.bkf-orbit-cc'),
  ev: root.querySelector('.bkf-orbit-ev'), sh: root.querySelector('.bkf-orbit-sh'), dr: root.querySelector('.bkf-orbit-dr'),
  bar: root.querySelector('.bkf-orbit-bar i'),
};
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const HUB_LOGO = out.logo.innerHTML;
const DIR = { in: 'Into Concord', out: 'Out of Concord', two: 'Two-way' };
const N = btns.map((el) => ({
  el, ring: +el.dataset.ring, k: +el.style.getPropertyValue('--k'), of: +el.style.getPropertyValue('--of'),
  dir: el.dataset.dir, epm: +el.dataset.epm, x: 0, y: 0, acc: Math.random(), pk: [], flip: false,
}));
const TOTAL = N.reduce((s, n) => s + n.epm, 0);
const fmt = (v) => v.toLocaleString('en-US');

/* colours come from the custom properties, so re-theming the CSS re-themes the canvas */
const probe = document.createElement('span');
probe.style.cssText = 'position:absolute;visibility:hidden;pointer-events:none';
stage.append(probe);
const col = {};
function readColors() {
  for (const [k, v, fb] of [['gold', '--bkf-orbit-gold', '#d6c08c'], ['out', '--bkf-orbit-out', '#d9a79c']]) {
    probe.style.color = 'var(' + v + ')';
    col[k] = getComputedStyle(probe).color;
    if (ctx) { ctx.fillStyle = fb; ctx.fillStyle = col[k]; col[k] = ctx.fillStyle; }  /* keep a colour the canvas understood */
  }
}

let W = 0, cx = 0, cy = 0, R0 = 0, R1 = 0, nodeR = 24, hubR = 48, dpr = 1;
let rot0 = 0, rot1 = 0, speed = 1, target = 1, active = -1, pinned = -1, onScreen = true, raf = 0, last = performance.now();
const OFF1 = -14 * Math.PI / 180;

function measure() {
  W = stage.clientWidth;
