    out.logo.innerHTML = HUB_LOGO; out.name.textContent = 'All connectors'; out.cat.textContent = '12 live · 120+ in the catalogue';
    out.ev.textContent = fmt(TOTAL); out.sh.textContent = '100%'; out.dr.textContent = 'Both ways';
    out.bar.style.setProperty('--s', 1);
