@property --bkf-rows-hl { syntax: "<percentage>"; inherits: false; initial-value: 100%; }

.bkf-rows {
  --bkf-rows-paper: oklch(97.3% 0.012 92);
  --bkf-rows-ink: oklch(24% 0.03 262);
  --bkf-rows-accent: oklch(48% 0.13 258);
  --bkf-rows-marker: oklch(88% 0.11 352);
  --bkf-rows-sheet: oklch(99.4% 0.005 92);
  --bkf-rows-muted: color-mix(in oklch, var(--bkf-rows-ink) 62%, var(--bkf-rows-paper));
  --bkf-rows-rule: color-mix(in oklch, var(--bkf-rows-ink) 14%, transparent);
  --bkf-rows-serif: ui-serif, "New York", "Iowan Old Style", Charter, Georgia, serif;
  --bkf-rows-ease: cubic-bezier(.22, .9, .24, 1);
  container-name: bkf-rows;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkf-rows-paper);
  color: var(--bkf-rows-ink);
  font: 400 16px/1.6 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, figure, q) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
}
.bkf-rows-in { max-width: 1160px; margin-inline: auto; padding: clamp(36px, 7cqi, 96px) clamp(16px, 5cqi, 64px); }

.bkf-rows-head { display: grid; gap: 18px; padding-bottom: clamp(24px, 4cqi, 44px); border-bottom: 1px solid var(--bkf-rows-ink); }
.bkf-rows-kicker { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font: 600 13px/1.2 system-ui, sans-serif; letter-spacing: .02em;
  & svg { width: 20px; height: 20px; fill: none; stroke: var(--bkf-rows-accent); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & span { font-weight: 400; color: var(--bkf-rows-muted); }
}
.bkf-rows-title { max-width: 18ch; font: 500 clamp(36px, 6.2cqi, 72px)/1 var(--bkf-rows-serif); letter-spacing: -.025em; text-wrap: balance;
  & em { font-style: italic; color: var(--bkf-rows-accent); }
}

.bkf-rows-row {
  view-timeline-name: --bkf-rows-vt; view-timeline-axis: block;
  display: grid; gap: clamp(22px, 4cqi, 64px); align-items: center;
  grid-template-columns: minmax(0, 1fr); grid-template-areas: "copy" "art";
  padding-block: clamp(32px, 5cqi, 64px); border-bottom: 1px solid var(--bkf-rows-rule);
  &:last-child { border-bottom: 0; padding-bottom: 0; }
}
@container bkf-rows (min-width: 760px) {
  .bkf-rows-row { grid-template-columns: minmax(0, .95fr) minmax(0, 1.05fr); grid-template-areas: "copy art"; }
  .bkf-rows-row:nth-child(even) { grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr); grid-template-areas: "art copy"; }
}
.bkf-rows-copy { grid-area: copy; display: grid; gap: 14px; justify-items: start; max-width: 46ch;
  & h3 { font: 600 clamp(26px, 3.2cqi, 36px)/1.08 var(--bkf-rows-serif); letter-spacing: -.015em; text-wrap: balance; }
  & > p { color: color-mix(in oklch, var(--bkf-rows-ink) 82%, var(--bkf-rows-paper)); text-wrap: pretty; }
}
.bkf-rows-num { font: italic 400 clamp(40px, 5cqi, 60px)/.9 var(--bkf-rows-serif); color: var(--bkf-rows-accent); font-variant-numeric: lining-nums tabular-nums; }
.bkf-rows-points { display: grid; gap: 6px; margin-top: 4px; font-size: 14px; color: var(--bkf-rows-muted);
  & li { position: relative; padding-left: 20px; }
  & li::before { content: ""; position: absolute; left: 0; top: .78em; width: 11px; height: 1px; background: var(--bkf-rows-ink); }
  & b { color: var(--bkf-rows-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
}
.bkf-rows-art { grid-area: art; min-width: 0; }
.bkf-rows-sheet {
  position: relative; padding: clamp(18px, 3cqi, 30px); border: 1px solid var(--bkf-rows-rule); border-radius: 4px;
  background: var(--bkf-rows-sheet);
  box-shadow: 0 1px 0 color-mix(in oklch, var(--bkf-rows-ink) 6%, transparent), 0 30px 50px -36px color-mix(in oklch, var(--bkf-rows-ink) 45%, transparent), 10px 10px 0 -1px color-mix(in oklch, var(--bkf-rows-ink) 4%, var(--bkf-rows-paper));
}

/* row 1: page and highlighter */
.bkf-rows-src { font: 500 11.5px/1.3 system-ui, sans-serif; text-transform: uppercase; letter-spacing: .1em; color: var(--bkf-rows-muted); & i { text-transform: none; letter-spacing: 0; font-family: var(--bkf-rows-serif); font-size: 13px; } }
.bkf-rows-text { margin-top: 14px; font: 400 clamp(16px, 1.9cqi, 19px)/1.62 var(--bkf-rows-serif); text-wrap: pretty; hanging-punctuation: first; }
.bkf-rows-hl {
  color: inherit; padding: .05em 0;
  background: linear-gradient(100deg, color-mix(in oklch, var(--bkf-rows-marker) 70%, transparent), var(--bkf-rows-marker) 6% 94%, color-mix(in oklch, var(--bkf-rows-marker) 60%, transparent)) 0 60% / var(--bkf-rows-hl) 78% no-repeat;
}
.bkf-rows-margin {
  position: relative; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 8px; width: fit-content; max-width: 100%; margin: 16px 0 0 auto; padding: 8px 12px;
  border-left: 2px solid var(--bkf-rows-accent); background: color-mix(in oklch, var(--bkf-rows-accent) 7%, var(--bkf-rows-sheet)); font-size: 13px;
  & b { color: var(--bkf-rows-accent); font-weight: 650; }
  & span:last-child { color: var(--bkf-rows-muted); }
}

/* row 2: graph */
.bkf-rows-graph { display: block; width: 100%; height: auto; overflow: visible; font: 500 11px system-ui, sans-serif; }
.bkf-rows-e { fill: none; stroke: color-mix(in oklch, var(--bkf-rows-ink) 32%, transparent); stroke-width: 1.2; stroke-dasharray: 1; transition: stroke .2s, stroke-width .2s; }
.bkf-rows-n { cursor: default;
  & circle { fill: var(--bkf-rows-sheet); stroke: var(--bkf-rows-ink); stroke-width: 1.5; transition: fill .2s; }
  & text { fill: var(--bkf-rows-ink); paint-order: stroke; stroke: var(--bkf-rows-sheet); stroke-width: 4px; stroke-linejoin: round; }
  &.is-hub circle { fill: var(--bkf-rows-accent); stroke: var(--bkf-rows-accent); }
  &.is-hub text { font: italic 600 14px var(--bkf-rows-serif); }
  &:hover circle { fill: var(--bkf-rows-marker); }
}
.bkf-rows-n { transform-box: fill-box; transform-origin: center; }
.bkf-rows-graph:has([data-n="att"]:hover) .bkf-rows-e[data-e~="att"] { stroke: var(--bkf-rows-accent); stroke-width: 2; }
.bkf-rows-graph:has([data-n="deep"]:hover) .bkf-rows-e[data-e~="deep"] { stroke: var(--bkf-rows-accent); stroke-width: 2; }
.bkf-rows-graph:has([data-n="bore"]:hover) .bkf-rows-e[data-e~="bore"] { stroke: var(--bkf-rows-accent); stroke-width: 2; }
.bkf-rows-graph:has([data-n="flow"]:hover) .bkf-rows-e[data-e~="flow"] { stroke: var(--bkf-rows-accent); stroke-width: 2; }
.bkf-rows-graph:has([data-n="oka"]:hover) .bkf-rows-e[data-e~="oka"] { stroke: var(--bkf-rows-accent); stroke-width: 2; }
.bkf-rows-graph:has([data-n="log"]:hover) .bkf-rows-e[data-e~="log"] { stroke: var(--bkf-rows-accent); stroke-width: 2; }
.bkf-rows-graph:has([data-n="ess"]:hover) .bkf-rows-e[data-e~="ess"] { stroke: var(--bkf-rows-accent); stroke-width: 2; }
.bkf-rows-cap { display: flex; flex-wrap: wrap; gap: 4px 16px; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--bkf-rows-rule); font: 500 11.5px/1.2 system-ui, sans-serif; text-transform: uppercase; letter-spacing: .08em; color: var(--bkf-rows-muted); font-variant-numeric: tabular-nums; }

/* row 3: editor */
.bkf-rows-ebar { display: flex; justify-content: space-between; padding-bottom: 10px; margin-bottom: 14px; border-bottom: 1px solid var(--bkf-rows-rule); font: 500 11.5px/1 system-ui, sans-serif; text-transform: uppercase; letter-spacing: .08em; color: var(--bkf-rows-muted); font-variant-numeric: tabular-nums; }
.bkf-rows-prev { font: 400 clamp(15px, 1.7cqi, 17px)/1.6 var(--bkf-rows-serif); color: var(--bkf-rows-muted); text-wrap: pretty; }
.bkf-rows-line { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 8px; margin-top: 10px; font: 400 clamp(15px, 1.9cqi, 18.5px)/1.5 var(--bkf-rows-serif); }
.bkf-rows-typed { white-space: nowrap;
  & > span { position: relative; }
  & > span::after { content: ""; position: absolute; right: -1px; top: .14em; bottom: .06em; width: 2px; border-radius: 1px; background: var(--bkf-rows-accent); opacity: 0; }
