/* Where scroll-driven animations exist the CSS does everything. Otherwise each row
   starts its time-based sequence the first time it is a third on screen. */
const scrubbed = window.CSS && CSS.supports('animation-timeline: view()');
const rows = [...root.querySelectorAll('.bkf-rows-row')];
if (!scrubbed) {
  if (!('IntersectionObserver' in window) || matchMedia('(prefers-reduced-motion: reduce)').matches) {
    rows.forEach((r) => r.classList.add('is-in'));
  } else {
    const io = new IntersectionObserver((es) => {
      if (!root.isConnected) { io.disconnect(); return; }
      for (const e of es) if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); }
    }, { threshold: 0, rootMargin: '0px 0px -25% 0px' });
    rows.forEach((r) => io.observe(r));
  }
}

