@property --bkf-spotlight-glow { syntax: "<number>"; inherits: false; initial-value: 0; }

.bkf-spotlight {
  --bkf-spotlight-bg: oklch(15.5% 0.006 255);
  --bkf-spotlight-ink: oklch(95.5% 0.006 255);
  --bkf-spotlight-accent: oklch(76% 0.16 60);
