  --bkf-spotlight-ease: cubic-bezier(.2, .8, .2, 1);
  --bkf-spotlight-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  container-name: bkf-spotlight;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  background: var(--bkf-spotlight-bg);
  color: var(--bkf-spotlight-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul, dl, dd) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
}
