  & svg { width: 20px; height: 20px; fill: none; stroke: var(--bkf-spotlight-accent); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & span { font-weight: 400; color: var(--bkf-spotlight-muted); }
}
.bkf-spotlight-title { margin-top: 16px; font-size: clamp(32px, 5cqi, 58px); line-height: 1; font-weight: 700; letter-spacing: -.04em; text-wrap: balance; }
.bkf-spotlight-side { display: grid; gap: 18px; justify-items: start;
  & > p { color: var(--bkf-spotlight-muted); font-size: clamp(15px, 1.45cqi, 16.5px); text-wrap: pretty; max-width: 48ch; }
