  transition: transform .4s var(--bkf-spotlight-spring), filter .2s;
  &:hover { transform: translateY(-1px); filter: brightness(1.06); }
  &:active { transform: scale(.97); }
}
.bkf-spotlight-link { color: var(--bkf-spotlight-ink); font-weight: 600; font-size: 14px; text-decoration: none;
