.bkf-spotlight :is(a, button):focus-visible { outline: 2px solid var(--bkf-spotlight-accent); outline-offset: 3px; }

/* ---------- the grid: 1px gaps reveal one radial gradient that follows the pointer ---------- */
.bkf-spotlight-grid {
  --x: 50%; --y: -200px;
  position: relative; display: grid; gap: 1px; padding: 1px; border-radius: 20px; overflow: hidden;
  grid-template-columns: minmax(0, 1fr);
  background:
    radial-gradient(380px circle at var(--x) var(--y), color-mix(in oklch, var(--bkf-spotlight-accent) calc(var(--bkf-spotlight-glow) * 85%), var(--bkf-spotlight-line)), transparent 70%),
    var(--bkf-spotlight-line);
  transition: --bkf-spotlight-glow .45s var(--bkf-spotlight-ease);
}
.bkf-spotlight-grid.is-lit { --bkf-spotlight-glow: 1; }
