@container bkf-spotlight (min-width: 920px) { .bkf-spotlight-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } .bkf-spotlight-cell { min-height: 266px !important; } }
.bkf-spotlight-grid > li { display: grid; }

.bkf-spotlight-cell {
  --cx: 88%; --cy: 18%;
  position: relative; isolation: isolate; overflow: hidden; display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 16px; align-items: start;
  width: 100%; padding: 20px; border: 0; border-radius: 0; background: var(--bkf-spotlight-surface); color: inherit; font: inherit; text-align: left; cursor: pointer;
  &::before { content: ""; position: absolute; inset: 0; z-index: -1; opacity: 0; transition: opacity .35s var(--bkf-spotlight-ease);
    background: radial-gradient(300px circle at var(--cx) var(--cy), color-mix(in oklch, var(--bkf-spotlight-accent) 13%, transparent), transparent 65%); }
  &::after { content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none; opacity: .55; transition: opacity .35s;
    background: radial-gradient(circle, color-mix(in oklch, var(--bkf-spotlight-ink) 22%, transparent) 1px, transparent 1.6px) 0 0 / 14px 14px;
    mask: radial-gradient(170px circle at var(--cx) var(--cy), #000, transparent 72%); }
  &:hover::before, &:focus-visible::before, &[aria-pressed="true"]::before { opacity: 1; }
  &:hover::after, &:focus-visible::after { opacity: 1; }
  &:focus-visible { outline-offset: -3px; border-radius: 4px; }
}
@container bkf-spotlight (min-width: 560px) {
  .bkf-spotlight-cell { display: flex; flex-direction: column; gap: 18px; min-height: 232px; padding: 24px; }
}
.bkf-spotlight-ico {
  display: grid; place-items: center; width: 44px; height: 44px; border-radius: 12px; border: 1px solid var(--bkf-spotlight-line);
  background: color-mix(in oklch, var(--bkf-spotlight-ink) 4%, var(--bkf-spotlight-bg)); color: var(--bkf-spotlight-ink);
  transition: color .3s, border-color .3s, transform .6s var(--bkf-spotlight-spring), background-color .3s;
  & svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; overflow: visible; }
}
.bkf-spotlight-txt { display: grid; grid-template-rows: auto auto 1fr; min-width: 0; }
@container bkf-spotlight (min-width: 560px) {
  .bkf-spotlight-txt { margin-top: auto; grid-template-rows: auto auto 0fr; transition: grid-template-rows .55s var(--bkf-spotlight-ease); }
}
.bkf-spotlight-name { font-weight: 650; font-size: 16px; letter-spacing: -.01em; }
.bkf-spotlight-meta { margin-top: 3px; font: 500 12px/1.4 ui-monospace, Menlo, monospace; color: var(--bkf-spotlight-muted); font-variant-numeric: tabular-nums; }
.bkf-spotlight-desc { min-height: 0; overflow: hidden;
  & > span { display: block; padding-top: 10px; font-size: 13.5px; line-height: 1.5; color: color-mix(in oklch, var(--bkf-spotlight-ink) 78%, var(--bkf-spotlight-bg)); text-wrap: pretty; }
}
@container bkf-spotlight (min-width: 560px) {
  .bkf-spotlight-desc > span { opacity: 0; transform: translateY(8px); clip-path: inset(0 0 100% 0); transition: opacity .35s, transform .5s var(--bkf-spotlight-ease), clip-path .5s var(--bkf-spotlight-ease); }
  .bkf-spotlight-cell:is(:hover, :focus-visible, [aria-pressed="true"]) {
    & .bkf-spotlight-txt { grid-template-rows: auto auto 1fr; }
    & .bkf-spotlight-desc > span { opacity: 1; transform: none; clip-path: inset(0 0 -4px 0); transition-delay: .06s; }
  }
}
.bkf-spotlight-cell:is(:hover, :focus-visible, [aria-pressed="true"]) .bkf-spotlight-ico { color: var(--bkf-spotlight-accent); border-color: color-mix(in oklch, var(--bkf-spotlight-accent) 45%, transparent); transform: translateY(-2px); background: color-mix(in oklch, var(--bkf-spotlight-accent) 8%, var(--bkf-spotlight-bg)); }
.bkf-spotlight-pin { position: absolute; top: 16px; right: 16px; width: 8px; height: 8px; border-radius: 50%; background: var(--bkf-spotlight-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--bkf-spotlight-accent) 20%, transparent); opacity: 0; transform: scale(.3); transition: opacity .25s, transform .45s var(--bkf-spotlight-spring); }
.bkf-spotlight-cell[aria-pressed="true"] .bkf-spotlight-pin { opacity: 1; transform: none; }

@media (hover: none) {
  .bkf-spotlight .bkf-spotlight-txt { grid-template-rows: auto auto 1fr; }
  .bkf-spotlight .bkf-spotlight-desc > span { opacity: 1; transform: none; clip-path: none; }
}

/* ---------- icon micro-animations ---------- */
.bkf-spotlight-ico svg * { transform-box: view-box; transform-origin: 12px 12px; }
.bkf-spotlight-k { transform-origin: 8px 15.5px !important; transition: transform .6s var(--bkf-spotlight-spring); }
.bkf-spotlight-h { transition: transform .9s var(--bkf-spotlight-ease); }
.bkf-spotlight-d { stroke-dasharray: 1; stroke-dashoffset: 0; }
.bkf-spotlight-p { transition: transform .5s var(--bkf-spotlight-spring), opacity .3s; }
.bkf-spotlight-s { transition: transform .5s var(--bkf-spotlight-spring); }
.bkf-spotlight-b { fill: currentColor; stroke: none; opacity: .0; }
.bkf-spotlight-cell:is(:hover, :focus-visible, [aria-pressed="true"]) {
  & .bkf-spotlight-k { transform: rotate(-24deg); }
  & .bkf-spotlight-h { transform: rotate(360deg); }
  & .bkf-spotlight-c { animation: bkf-spotlight-blink 1s steps(2, jump-none) infinite; }
  & .bkf-spotlight-d { animation: bkf-spotlight-draw .7s var(--bkf-spotlight-ease) both; }
  & .bkf-spotlight-p { transform: translateX(1.5px); }
  & .bkf-spotlight-s { transform: translateY(-2.5px); }
  & .bkf-spotlight-r { animation: bkf-spotlight-sweep 1.6s linear infinite; }
  & .bkf-spotlight-b { animation: bkf-spotlight-ping 1.6s ease-out infinite; }
}
.bkf-spotlight-cell:not(:hover, :focus-visible, [aria-pressed="true"]) .bkf-spotlight-p { opacity: .55; }
@keyframes bkf-spotlight-blink { 0% { opacity: 1; } 100% { opacity: 0; } }
@keyframes bkf-spotlight-draw { from { stroke-dashoffset: 1; } }
@keyframes bkf-spotlight-sweep { to { transform: rotate(360deg); } }
@keyframes bkf-spotlight-ping { 0%, 30% { opacity: 0; } 40% { opacity: 1; } 100% { opacity: 0; } }

.bkf-spotlight-cell > :is(.bkf-spotlight-ico, .bkf-spotlight-txt) { animation: bkf-spotlight-in .8s var(--bkf-spotlight-ease) backwards; animation-delay: calc(var(--d, 0) * 1ms); }
.bkf-spotlight-cell > .bkf-spotlight-txt { animation-delay: calc(var(--d, 0) * 1ms + 80ms); }
@keyframes bkf-spotlight-in { from { opacity: 0; transform: translateY(14px); filter: blur(4px); } }
.bkf-spotlight:not(.is-seen) .bkf-spotlight-cell > * { animation-play-state: paused; }

/* ---------- stats ---------- */
.bkf-spotlight-stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px 24px; margin-top: clamp(24px, 3.4cqi, 40px); padding-top: 22px; border-top: 1px solid var(--bkf-spotlight-line);
  & dt { font-size: 12.5px; color: var(--bkf-spotlight-muted); }
  & dd { margin-top: 2px; font-size: clamp(22px, 2.6cqi, 30px); font-weight: 650; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
}
@container bkf-spotlight (min-width: 760px) { .bkf-spotlight-stats { grid-template-columns: repeat(4, minmax(0, 1fr)); } }

@media (prefers-reduced-motion: reduce) {
  .bkf-spotlight .bkf-spotlight-cell > * { animation: none; }
  .bkf-spotlight :is(.bkf-spotlight-txt, .bkf-spotlight-desc > span, .bkf-spotlight-ico, .bkf-spotlight-k, .bkf-spotlight-h, .bkf-spotlight-p, .bkf-spotlight-s, .bkf-spotlight-pin) { transition-duration: .01s !important; }
  .bkf-spotlight .bkf-spotlight-cell :is(.bkf-spotlight-c, .bkf-spotlight-d, .bkf-spotlight-r, .bkf-spotlight-b) { animation: none !important; }
  .bkf-spotlight .bkf-spotlight-cell .bkf-spotlight-h { transform: none !important; }
}

