const grid = root.querySelector('.bkf-spotlight-grid');
const cells = [...root.querySelectorAll('.bkf-spotlight-cell')];
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const uid = Math.random().toString(36).slice(2, 8);

/* concise accessible names: the title names the button, meta + description describe it */
cells.forEach((c, i) => {
  const n = c.querySelector('.bkf-spotlight-name'), m = c.querySelector('.bkf-spotlight-meta'), d = c.querySelector('.bkf-spotlight-desc');
  n.id = 'bkf-spotlight-n' + i + uid; m.id = 'bkf-spotlight-m' + i + uid; d.id = 'bkf-spotlight-d' + i + uid;
  c.setAttribute('aria-labelledby', n.id);
  c.setAttribute('aria-describedby', m.id + ' ' + d.id);
  c.tabIndex = i === 0 ? 0 : -1;
});

/* stagger the entrance by grid position, not DOM order: diagonal waves read better */
function cols() { return getComputedStyle(grid).gridTemplateColumns.split(' ').length; }
function stagger() {
  const n = cols();
  cells.forEach((c, i) => c.parentElement.style.setProperty('--d', ((i % n) + Math.floor(i / n)) * 70));
}
stagger();

/* geometry cached on resize; pointer moves cost one rect read per frame */
let offs = [], pending = null, raf = 0;
function cache() { offs = cells.map((c) => [c.offsetLeft, c.offsetTop, c.offsetWidth, c.offsetHeight]); }
const ro = new ResizeObserver(() => { cache(); stagger(); });
ro.observe(grid);
function paint() {
  if (!root.isConnected) return;
  raf = 0;
  if (!pending) return;
  const r = grid.getBoundingClientRect();
  const x = pending.x - r.left, y = pending.y - r.top;
  grid.style.setProperty('--x', x + 'px');
  grid.style.setProperty('--y', y + 'px');
  const hit = pending.cell;
  if (hit) {
    const o = offs[cells.indexOf(hit)];
    if (o) { hit.style.setProperty('--cx', (x - o[0]) + 'px'); hit.style.setProperty('--cy', (y - o[1]) + 'px'); }
  }
  pending = null;
}
grid.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'touch') return;
  pending = { x: e.clientX, y: e.clientY, cell: e.target.closest('.bkf-spotlight-cell') };
  grid.classList.add('is-lit');
  if (!raf) raf = requestAnimationFrame(paint);
});
grid.addEventListener('pointerleave', () => grid.classList.remove('is-lit'));

/* keyboard users get the same light: centre it on the focused cell */
grid.addEventListener('focusin', (e) => {
  const c = e.target.closest('.bkf-spotlight-cell');
  if (!c || !c.matches(':focus-visible')) return;
  const o = offs[cells.indexOf(c)] || [0, 0, 0, 0];
  grid.style.setProperty('--x', (o[0] + o[2] / 2) + 'px');
  grid.style.setProperty('--y', (o[1] + o[3] / 2) + 'px');
  c.style.setProperty('--cx', o[2] / 2 + 'px');
  c.style.setProperty('--cy', o[3] / 2 + 'px');
  grid.classList.add('is-lit');
});
grid.addEventListener('focusout', (e) => { if (!grid.contains(e.relatedTarget)) grid.classList.remove('is-lit'); });

cells.forEach((c) => c.addEventListener('click', () => {
  c.setAttribute('aria-pressed', String(c.getAttribute('aria-pressed') !== 'true'));
}));
grid.addEventListener('keydown', (e) => {
  const i = cells.indexOf(document.activeElement);
  if (i < 0) return;
  if (e.key === 'Escape') { cells.forEach((c) => c.setAttribute('aria-pressed', 'false')); return; }
  const n = cols();
  const map = { ArrowRight: i + 1, ArrowLeft: i - 1, ArrowDown: i + n, ArrowUp: i - n, Home: 0, End: cells.length - 1 };
  if (!(e.key in map)) return;
  e.preventDefault();
  const j = Math.max(0, Math.min(cells.length - 1, map[e.key]));
  cells[i].tabIndex = -1; cells[j].tabIndex = 0; cells[j].focus();
});

if (reduce.matches || !('IntersectionObserver' in window)) root.classList.add('is-seen');
else {
  const io = new IntersectionObserver((es) => {
    if (!root.isConnected) { io.disconnect(); ro.disconnect(); return; }
    if (es.some((x) => x.isIntersecting)) { root.classList.add('is-seen'); io.disconnect(); }
  }, { threshold: 0, rootMargin: '0px 0px -18% 0px' });
  io.observe(root);
}

