.bkf-reel {
  --bkf-reel-bg: oklch(13.5% 0.008 40);
  --bkf-reel-ink: oklch(93% 0.012 80);
  --bkf-reel-accent: oklch(63% 0.2 28);
  --bkf-reel-muted: color-mix(in oklch, var(--bkf-reel-ink) 55%, var(--bkf-reel-bg));
  --bkf-reel-line: color-mix(in oklch, var(--bkf-reel-ink) 13%, transparent);
  --bkf-reel-card-w: min(84cqi, 440px);
  --bkf-reel-ease: cubic-bezier(.16, 1, .3, 1);
  container-name: bkf-reel;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  overflow: hidden;
  background:
    radial-gradient(70% 55% at 50% 100%, color-mix(in oklch, var(--bkf-reel-accent) 10%, transparent), transparent 70%),
    var(--bkf-reel-bg);
  color: var(--bkf-reel-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, fieldset, legend) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
}
.bkf-reel-in { timeline-scope: --bkf-reel-tl; padding-block: clamp(32px, 6cqi, 80px); }
.bkf-reel-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 20px; max-width: 1240px; margin: 0 auto clamp(22px, 3.4cqi, 40px); padding-inline: clamp(16px, 4.5cqi, 56px); }
.bkf-reel-eyebrow { display: flex; align-items: center; gap: 8px; font-weight: 650; font-size: 13.5px;
  & svg { width: 20px; height: 20px; fill: none; stroke: var(--bkf-reel-accent); stroke-width: 1.5; stroke-linejoin: round; }
  & span { color: var(--bkf-reel-muted); font-weight: 400; }
}
.bkf-reel-title { margin-top: 14px; max-width: 16ch; font-size: clamp(32px, 5.2cqi, 60px); line-height: 1; font-weight: 650; letter-spacing: -.04em; text-wrap: balance;
  & em { font-style: italic; font-weight: 400; color: var(--bkf-reel-accent); }
}
.bkf-reel-nav { display: flex; align-items: center; gap: 8px; }
.bkf-reel-count { margin-right: 10px; font: 500 13px/1 ui-monospace, Menlo, monospace; color: var(--bkf-reel-muted); font-variant-numeric: tabular-nums; & b { color: var(--bkf-reel-ink); font-weight: 600; } }
.bkf-reel-btn {
  display: grid; place-items: center; width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--bkf-reel-line); background: color-mix(in oklch, var(--bkf-reel-ink) 4%, transparent);
  color: var(--bkf-reel-ink); cursor: pointer; transition: background-color .2s, border-color .2s, transform .4s var(--bkf-reel-ease), opacity .2s;
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  &:hover:not(:disabled) { background: var(--bkf-reel-ink); color: var(--bkf-reel-bg); }
  &:active:not(:disabled) { transform: scale(.94); }
  &:disabled { opacity: .3; cursor: default; }
}
.bkf-reel :is(button, input, .bkf-reel-track):focus-visible { outline: 2px solid var(--bkf-reel-accent); outline-offset: 3px; }

/* ---------- track ---------- */
.bkf-reel-track {
  position: relative; /* offsetLeft of the cards is measured from the track */
  display: grid; grid-auto-flow: column; grid-auto-columns: var(--bkf-reel-card-w); gap: clamp(14px, 2.4cqi, 28px);
  overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x mandatory; scrollbar-width: none;
  padding: 6px calc((100cqi - var(--bkf-reel-card-w)) / 2) 12px;
  scroll-timeline: --bkf-reel-tl inline;
  &::-webkit-scrollbar { display: none; }
  &:focus-visible { outline-offset: -2px; border-radius: 8px; }
}
.bkf-reel-card { scroll-snap-align: center; display: grid; gap: 16px; align-content: start; transform-origin: 50% 40%; }
.bkf-reel-cap { display: grid; grid-template-columns: auto minmax(0, 1fr); column-gap: 14px; row-gap: 6px; padding-inline: 2px;
  & h3 { font-size: 18px; line-height: 1.25; font-weight: 620; letter-spacing: -.015em; text-wrap: balance; }
  & p { grid-column: 2; font-size: 14px; line-height: 1.5; color: var(--bkf-reel-muted); text-wrap: pretty; }
}
.bkf-reel-n { padding-top: 3px; font: 500 12px/1 ui-monospace, Menlo, monospace; color: var(--bkf-reel-accent); font-variant-numeric: tabular-nums; }

@supports (animation-timeline: view()) {
  .bkf-reel-card { animation: bkf-reel-focus linear both; animation-timeline: view(inline); }
  .bkf-reel-scrub i { animation: bkf-reel-thumb linear both; animation-timeline: --bkf-reel-tl; }
}
@keyframes bkf-reel-focus {
  0% { transform: scale(.84) translateY(18px); opacity: .32; }
  38%, 62% { transform: none; opacity: 1; }
  100% { transform: scale(.84) translateY(18px); opacity: .32; }
}
@keyframes bkf-reel-thumb { from { transform: translateX(0); } to { transform: translateX(calc(100% * 4)); } }
@supports not (animation-timeline: view()) {
  .bkf-reel-card { transition: transform .6s var(--bkf-reel-ease), opacity .6s var(--bkf-reel-ease); transform: scale(.88) translateY(14px); opacity: .4; }
  .bkf-reel-card.is-current { transform: none; opacity: 1; }
  .bkf-reel-scrub i { transform: translateX(calc(var(--bkf-reel-p, 0) * 100% * 4)); }
}
.bkf-reel-scrub { position: relative; width: min(240px, 60cqi); height: 3px; margin: 18px auto 0; border-radius: 3px; background: var(--bkf-reel-line); overflow: hidden;
  & i { position: absolute; inset: 0 auto 0 0; width: calc(100% / 5); border-radius: inherit; background: var(--bkf-reel-ink); }
}

/* ---------- the photograph, drawn in CSS ---------- */
.bkf-reel-shot { position: relative; isolation: isolate; aspect-ratio: 4 / 3; overflow: hidden; border-radius: 14px; background: oklch(20% 0.02 40);
  box-shadow: 0 0 0 1px var(--bkf-reel-line), 0 30px 60px -30px oklch(0% 0 0 / .9); }
.bkf-reel-scene { position: absolute; inset: 0; transition: filter .7s var(--bkf-reel-ease);
  & > span { position: absolute; }
}
.bkf-reel-sky { inset: 0; background: linear-gradient(180deg, oklch(36% 0.06 268) 0%, oklch(52% 0.09 10) 34%, oklch(71% 0.14 45) 54%, oklch(85% 0.11 78) 64%); }
.bkf-reel-sun { left: 38%; top: 60%; width: 20%; aspect-ratio: 1; border-radius: 50%; translate: -50% -50%;
  background: radial-gradient(circle, oklch(99% 0.03 95) 0 28%, oklch(92% 0.12 80) 42%, oklch(84% 0.14 60 / .5) 56%, transparent 71%); }
.bkf-reel-sea { inset: 66% 0 0; background: linear-gradient(180deg, oklch(62% 0.1 45), oklch(34% 0.05 280) 70%, oklch(22% 0.03 280));
  &::after { content: ""; position: absolute; left: 38%; top: 0; width: 16%; height: 100%; translate: -50% 0;
    background: repeating-linear-gradient(180deg, oklch(95% 0.08 85 / .85) 0 2px, transparent 2px 7px);
    mask: linear-gradient(180deg, #000, transparent 85%); }
}
.bkf-reel-h1 { inset: 50% 0 34% 0; background: oklch(32% 0.05 25);
  clip-path: polygon(0 48%, 9% 30%, 18% 44%, 26% 26%, 31% 60%, 52% 70%, 60% 40%, 70% 22%, 80% 38%, 90% 16%, 100% 30%, 100% 100%, 0 100%); }
.bkf-reel-h2 { inset: 36% 0 0 64%; background: oklch(17% 0.02 30);
  clip-path: polygon(30% 0, 46% 6%, 58% 22%, 74% 26%, 100% 20%, 100% 100%, 0 100%, 6% 70%, 14% 40%); }

/* 1: grain */
.bkf-reel-grain { position: absolute; inset: -30%; width: 160%; height: 160%; mix-blend-mode: overlay; opacity: .55; pointer-events: none; will-change: transform;
  animation: bkf-reel-jitter .48s steps(1) infinite; }
@keyframes bkf-reel-jitter { 0% { transform: translate(0, 0); } 17% { transform: translate(-6%, 4%); } 33% { transform: translate(5%, -7%); } 50% { transform: translate(-3%, -2%); } 67% { transform: translate(7%, 5%); } 83% { transform: translate(-8%, 2%); } }
.bkf-reel-tag { position: absolute; left: 12px; bottom: 12px; z-index: 2; max-width: calc(100% - 24px); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding: 5px 9px; border-radius: 7px; background: oklch(10% 0.01 40 / .6); backdrop-filter: blur(8px);
  font: 500 11.5px/1 ui-monospace, Menlo, monospace; color: var(--bkf-reel-ink); }

/* 2: halation, three strengths from radio inputs via :has() */
.bkf-reel-halo { position: absolute; left: 38%; top: 60%; width: 34%; aspect-ratio: 1; translate: -50% -50%; border-radius: 50%; pointer-events: none;
  background: radial-gradient(circle, oklch(66% 0.24 28 / .0) 22%, oklch(64% 0.24 28 / .75) 34%, oklch(55% 0.22 25 / .25) 52%, transparent 70%);
  mix-blend-mode: screen; filter: blur(6px); opacity: .6; transition: opacity .5s var(--bkf-reel-ease), scale .7s var(--bkf-reel-ease);
  animation: bkf-reel-breathe 4s ease-in-out infinite; }
@keyframes bkf-reel-breathe { 50% { transform: scale(1.06); } }
.bkf-reel-k-halo .bkf-reel-h1, .bkf-reel-k-halo .bkf-reel-h2 { transition: filter .5s; }
.bkf-reel-card:has(input[name^="bkf-reel-halo"][value="0"]:checked) .bkf-reel-halo { opacity: 0; scale: .8; }
.bkf-reel-card:has(input[name^="bkf-reel-halo"][value="2"]:checked) {
  & .bkf-reel-halo { opacity: 1; scale: 1.25; }
  & :is(.bkf-reel-h1, .bkf-reel-h2) { filter: drop-shadow(0 -1px 2px oklch(62% 0.24 28)); }
  & .bkf-reel-sun { filter: drop-shadow(0 0 10px oklch(62% 0.24 28)); }
}
.bkf-reel-seg, .bkf-reel-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 6px;
  & legend { float: left; margin-right: 6px; font: 500 11.5px/1 ui-monospace, Menlo, monospace; text-transform: uppercase; letter-spacing: .08em; color: var(--bkf-reel-muted); }
  & label { position: relative; cursor: pointer; }
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & label span { display: block; padding: 6px 11px; border: 1px solid var(--bkf-reel-line); border-radius: 99px; font-size: 12.5px; font-weight: 550; transition: background-color .2s, color .2s, border-color .2s; }
  & label:hover span { border-color: var(--bkf-reel-muted); }
  & input:checked + span { background: var(--bkf-reel-ink); color: var(--bkf-reel-bg); border-color: var(--bkf-reel-ink); }
  & input:focus-visible + span { outline: 2px solid var(--bkf-reel-accent); outline-offset: 2px; }
}
.bkf-reel-more { font-size: 12.5px; color: var(--bkf-reel-muted); padding-left: 4px; }

/* 3: before / after */
.bkf-reel-k-split { --split: 46%; touch-action: pan-y; }
.bkf-reel-flat, .bkf-reel-graded { position: absolute; inset: 0; }
.bkf-reel-flat .bkf-reel-scene { filter: saturate(.45) contrast(.82) brightness(1.08); }
.bkf-reel-graded { clip-path: inset(0 0 0 var(--split)); }
.bkf-reel-graded .bkf-reel-scene { filter: saturate(1.18) contrast(1.12) sepia(.12); }
.bkf-reel-divider { position: absolute; top: 0; bottom: 0; left: var(--split); z-index: 2; width: 2px; margin-left: -1px; background: var(--bkf-reel-ink); pointer-events: none;
  &::after { content: ""; position: absolute; top: 50%; left: 50%; width: 30px; height: 30px; translate: -50% -50%; border-radius: 50%; background: var(--bkf-reel-ink);
    box-shadow: 0 4px 14px oklch(0% 0 0 / .5);
    mask: radial-gradient(circle, #000 0 9px, transparent 9.5px), linear-gradient(#000 0 0); mask-composite: exclude; }
}
.bkf-reel-lab { position: absolute; top: 12px; left: 12px; z-index: 2; padding: 4px 8px; border-radius: 6px; background: oklch(10% 0.01 40 / .55); font: 500 11px/1 ui-monospace, Menlo, monospace; text-transform: uppercase; letter-spacing: .06em; pointer-events: none;
  &.is-r { left: auto; right: 12px; } }
.bkf-reel-range { position: absolute; inset: 0; z-index: 3; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: ew-resize; accent-color: var(--bkf-reel-accent); }

/* 4: stocks */
.bkf-reel-card:has(input[value="meridian"]:checked) .bkf-reel-k-stock .bkf-reel-scene { filter: saturate(1.05) contrast(1.04) sepia(.08); }
.bkf-reel-card:has(input[value="tallow"]:checked) .bkf-reel-k-stock .bkf-reel-scene { filter: hue-rotate(-16deg) saturate(1.3) contrast(1.14) brightness(.94); }
.bkf-reel-card:has(input[value="pale"]:checked) .bkf-reel-k-stock .bkf-reel-scene { filter: saturate(.62) contrast(.86) brightness(1.12) sepia(.1); }
.bkf-reel-card:has(input[value="rook"]:checked) .bkf-reel-k-stock .bkf-reel-scene { filter: grayscale(1) contrast(1.32) brightness(1.02); }

/* 5: batch develop, a diagonal wave across the contact sheet */
.bkf-reel-k-batch { background: oklch(16% 0.01 40); }
.bkf-reel-roll { position: absolute; inset: 10px 10px 42px; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; }
.bkf-reel-roll span { border-radius: 3px; filter: hue-rotate(var(--h)) saturate(1.1);
  background:
    radial-gradient(circle at 38% 62%, oklch(97% 0.04 95) 0 5%, oklch(88% 0.12 75) 9%, transparent 16%),
    linear-gradient(180deg, transparent 60%, oklch(30% 0.04 25) 60% 68%, oklch(50% 0.09 40) 68%, oklch(26% 0.04 280)),
    linear-gradient(180deg, oklch(38% 0.06 268), oklch(55% 0.1 15) 35%, oklch(75% 0.13 50) 58%);
