@keyframes bkf-reel-develop {
  0%, 6% { filter: hue-rotate(var(--h)) grayscale(1) brightness(.35) contrast(.8); }
  22%, 88% { filter: hue-rotate(var(--h)) saturate(1.1); }
  100% { filter: hue-rotate(var(--h)) grayscale(1) brightness(.35) contrast(.8); }
}

.bkf-reel.is-off :is(.bkf-reel-grain, .bkf-reel-halo, .bkf-reel-roll span) { animation-play-state: paused; }

@container bkf-reel (max-width: 520px) {
  .bkf-reel-nav { width: 100%; }
  .bkf-reel-count { margin-right: auto; }
  .bkf-reel-cap { grid-template-columns: minmax(0, 1fr); & p { grid-column: 1; } }
}

@media (prefers-reduced-motion: reduce) {
  .bkf-reel .bkf-reel-card { animation: none; transform: none; opacity: 1; transition: none; }
  .bkf-reel :is(.bkf-reel-grain, .bkf-reel-halo, .bkf-reel-roll span) { animation: none; }
  .bkf-reel .bkf-reel-track { scroll-behavior: auto; }
  .bkf-reel .bkf-reel-scene { transition: none; }
}

