const track = root.querySelector('.bkf-reel-track');
const cards = [...root.querySelectorAll('.bkf-reel-card')];
const [prev, next] = root.querySelectorAll('.bkf-reel-btn');
const countEl = root.querySelector('.bkf-reel-count b');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const scrubbed = window.CSS && CSS.supports('animation-timeline: view()');
const uid = Math.random().toString(36).slice(2, 8);

/* radio groups are page-global by name: scope them to this instance */
root.querySelectorAll('input[type="radio"]').forEach((r) => { r.name = r.name + '-' + uid; });

let cur = -1, raf = 0;
function measure() {
  if (!root.isConnected) return;
  raf = 0;
  const mid = track.scrollLeft + track.clientWidth / 2;
  let best = 0, bd = Infinity;
  cards.forEach((c, i) => { const d = Math.abs(c.offsetLeft + c.offsetWidth / 2 - mid); if (d < bd) { bd = d; best = i; } });
  const max = track.scrollWidth - track.clientWidth;
  if (!scrubbed) root.style.setProperty('--bkf-reel-p', max > 0 ? (track.scrollLeft / max).toFixed(4) : 0);
  if (best !== cur) {
    cur = best;
    countEl.textContent = String(cur + 1).padStart(2, '0');
    cards.forEach((c, i) => c.classList.toggle('is-current', i === cur));
    prev.disabled = cur === 0;
    next.disabled = cur === cards.length - 1;
  }
}
track.addEventListener('scroll', () => { if (!raf) raf = requestAnimationFrame(measure); }, { passive: true });

function go(i) {
  i = Math.max(0, Math.min(cards.length - 1, i));
  const c = cards[i];
  track.scrollTo({ left: c.offsetLeft - (track.clientWidth - c.offsetWidth) / 2, behavior: reduce.matches ? 'auto' : 'smooth' });
}
prev.addEventListener('click', () => go(cur - 1));
next.addEventListener('click', () => go(cur + 1));
track.addEventListener('keydown', (e) => {
  if (e.target !== track) return;
  const map = { ArrowRight: cur + 1, ArrowLeft: cur - 1, Home: 0, End: cards.length - 1 };
  if (!(e.key in map)) return;
  e.preventDefault();
  go(map[e.key]);
});
/* clicking a side card brings it to the centre */
cards.forEach((c, i) => c.addEventListener('click', (e) => {
  if (i !== cur && !e.target.closest('input, label, button')) go(i);
}));

/* before / after: the range input drives one custom property */
const split = root.querySelector('.bkf-reel-k-split');
const range = root.querySelector('.bkf-reel-range');
const setSplit = () => split.style.setProperty('--split', range.value + '%');
range.addEventListener('input', setSplit);
setSplit();

const ro = new ResizeObserver(() => { cur = -1; measure(); });
ro.observe(track);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); ro.disconnect(); return; }
  root.classList.toggle('is-off', !es[es.length - 1].isIntersecting);
});
io.observe(root);
/* open on the second card so the reel reads as a reel: a neighbour on each side */
const c1 = cards[1];
track.scrollLeft = c1.offsetLeft - (track.clientWidth - c1.offsetWidth) / 2;
measure();
